/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A67 frozen manifest; 20-lemma checkpoints are validated before publication. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Claims are limited to the stated formation; uncertain history is left open.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});
D('maker',{etymology:E('Maker is formed from make with the agent suffix -er; it can name a person or company that produces goods, or someone who brings about a result.','maker'),contexts:[C('maker.s1','家具制造','The maker stamped its name beneath the table and listed the wood used in its construction.','制造商在桌子底部盖上名称，并注明制作所用的木材。','The maker stamped its name / beneath the table / and listed / the wood used in its construction.','maker.s1 指制造产品的人或公司，也可指造成某种结果的人。','产品标识和材料说明表明这是生产者。')],mistakes:[M('The company was called the maker even though it produced no goods and had no role in the table’s creation.','The company was the maker because its workshop built the table.','没有参与制造就不是该产品的 maker。')],quiz:[Q('maker',1,1,'A furniture maker is a person or firm that?','produces furniture','repairs only computer software','rents out an apartment','produces furniture','maker.s1 指产品制造者。'),Q('maker',2,1,'Which phrase is natural?','the maker of the instrument','the maker to the instrument yesterday','the instrument makered','the maker of the instrument','maker 常与 of 连用表示某物的制造者。','collocation'),Q('maker',3,1,'A decision-maker is someone who?','makes or determines decisions','only records decisions after the fact','sells musical instruments','makes or determines decisions','maker 也可指造成某种结果的人。'),Q('maker',4,1,'Maker is formed from which verb?','make','mangle','manage','make','maker 由 make 加 -er 构成。','word-formation')]});
D('makeshift',{etymology:E('Makeshift combines make and shift in the sense “manage or contrive”; it describes a temporary substitute improvised until something suitable is available.','makeshift'),contexts:[C('makeshift.s1','灾后安置','After the flood, volunteers built a makeshift bridge from planks so residents could reach the clinic.','洪水过后，志愿者用木板搭起一座临时桥，方便居民前往诊所。','After the flood / volunteers built a makeshift bridge / from planks / so residents could reach the clinic.','makeshift.s1 作形容词，表示临时凑合使用的。','木板桥仅在正式通道修复前暂时代用。')],mistakes:[M('The town called the permanent reinforced bridge a makeshift structure even though it was the final design built to last for generations.','The town used a makeshift plank crossing until the permanent bridge was repaired.','临时替代物与永久工程的性质相反。')],quiz:[Q('makeshift',1,1,'A makeshift shelter is?','a temporary substitute','a permanent palace','a shopping center','a temporary substitute','makeshift.s1 指临时的。'),Q('makeshift',2,2,'A makeshift may also be?','something improvised for temporary use','a manufacturer’s official name','a kind of illness','something improvised for temporary use','makeshift.s2 可作名词指权宜之计。'),Q('makeshift',3,1,'Which is a makeshift repair?','using tape until a proper part arrives','installing the finished replacement permanently','ordering nothing and leaving the damage','using tape until a proper part arrives','胶带临时固定属于权宜处理。'),Q('makeshift',4,1,'Makeshift often implies that a solution is?','temporary and improvised','carefully planned as permanent','unrelated to the problem','temporary and improvised','该词常带临时凑合的意味。')]});
D('makeup',{etymology:E('Makeup is formed from make up; it refers to cosmetics, the composition of something, or a test or class arranged later for someone who missed the original.','makeup'),contexts:[C('makeup.s2','材料分析','The makeup of the alloy includes copper, nickel, and a small amount of zinc.','这种合金由铜、镍和少量锌构成。','The makeup of the alloy / includes copper, nickel, / and a small amount / of zinc.','makeup.s2 指构成某事物的各个部分及其组合。','句子列出合金的组成材料。')],mistakes:[M('The makeup of the alloy was described as its ingredients even though the sentence discussed only how shiny its surface looked.','The makeup of the alloy refers to the metals that compose it.','表面光泽不等于材料的组成。')],quiz:[Q('makeup',1,1,'Face makeup consists of?','cosmetics applied to change appearance','the parts of an alloy','an exam taken after an absence','cosmetics applied to change appearance','makeup.s1 指化妆品或妆容。'),Q('makeup',2,2,'The makeup of a committee is its?','composition of members','appearance after cosmetics','replacement exam','composition of members','makeup.s2 指构成。'),Q('makeup',3,3,'A makeup test is given to a student who?','missed the original test','already passed every class','teaches the course','missed the original test','makeup.s3 指补考或补课。'),Q('makeup',4,2,'Which sentence uses makeup to mean “composition”?','The makeup of the soil varies across the valley.','She applied makeup before the performance.','He took a makeup exam on Friday.','The makeup of the soil varies across the valley.','该句谈土壤的组成成分。')]});
D('making',{etymology:E('Making is formed from make with -ing; it names the act or process of creating something and can describe abilities that shape a person or outcome.','making'),contexts:[C('making.s1','陶艺课程','Making a clay bowl took the class longer than expected because each student shaped the rim by hand.','制作陶碗比全班预想的耗时更久，因为每位学生都要手工塑造碗沿。','Making a clay bowl / took the class longer than expected / because each student shaped / the rim by hand.','making.s1 指制作某物的行为或过程。','学生实际动手塑形完成陶碗。')],mistakes:[M('The making of the sculpture involved no shaping, assembling, or other act of creating it.','The making of the sculpture involved shaping the clay and firing it in a kiln.','没有任何制作行为就不存在 making 过程。')],quiz:[Q('making',1,1,'The making of a film refers to?','the process of producing it','the audience’s opinion only','the film’s ticket price','the process of producing it','making.s1 指制作过程。'),Q('making',2,2,'Someone’s making may refer to?','qualities that equip them for a role','their current makeup products','a late exam they missed','qualities that equip them for a role','making.s2 可指造就某类人的素质。'),Q('making',3,1,'Which phrase is natural?','the making of a wooden chair','the making under the chair of','the chair making yesterday it','the making of a wooden chair','making 常用 the making of 表示制作过程。','collocation'),Q('making',4,1,'Making is related to the verb?','make','malign','manure','make','making 是 make 的 -ing 形式。','word-formation')]});
D('maladroit',{etymology:E('Maladroit comes from French mal “badly” and adroit “skilled”; it describes someone clumsy or lacking skill with their hands or in dealing with people.','maladroit'),contexts:[C('maladroit.s1','手工操作','His maladroit attempt to tighten the tiny screw sent the screwdriver skidding across the bench.','他笨拙地想拧紧那颗小螺丝，结果螺丝刀滑到了工作台另一边。','His maladroit attempt / to tighten the tiny screw / sent the screwdriver / skidding across the bench.','maladroit 指手脚不灵巧，或处理人际关系时欠圆滑。','螺丝刀滑脱说明操作缺乏技巧。')],mistakes:[M('She handled the delicate glass expertly, yet the report called her maladroit with her hands.','She was maladroit with the glass and nearly dropped it while trying to carry it.','熟练稳妥的操作与笨拙相反。')],quiz:[Q('maladroit',1,1,'A maladroit movement is?','clumsy or unskillful','careful and precise','deliberately malicious','clumsy or unskillful','maladroit.s1 指不灵巧的。'),Q('maladroit',2,1,'Which action is maladroit?','knocking over a glass while fumbling with a tray','placing each glass steadily on the table','measuring a screw accurately','knocking over a glass while fumbling with a tray','笨手笨脚打翻杯子体现 maladroit。'),Q('maladroit',3,1,'A maladroit comment may be?','socially awkward or tactless','perfectly timed and considerate','a medical diagnosis','socially awkward or tactless','该词也可形容人际表达欠圆滑。'),Q('maladroit',4,1,'Maladroit is closest to?','clumsy','malevolent','manageable','clumsy','clumsy 与 maladroit 意义接近。','meaning')]});
D('malady',{etymology:E('Malady comes through Old French from Medieval Latin male habitus, “in a bad state”; it can mean a serious illness or, figuratively, a serious social problem.','malady'),contexts:[C('malady.s2','社会评论','The report described chronic housing insecurity as a malady that weakened the whole community.','报告把长期住房不稳定称为一种削弱整个社区的社会弊病。','The report described / chronic housing insecurity / as a malady / that weakened the whole community.','malady.s2 可比喻社会或制度中的严重弊病。','住房不稳定影响整个社区，不只是个别家庭。')],mistakes:[M('The essay called a minor scheduling inconvenience a grave social malady even though it affected no one beyond a single afternoon.','The essay described entrenched poverty as a social malady affecting the whole region.','短暂轻微的不便不足以称为严重社会弊病。')],quiz:[Q('malady',1,1,'A malady can mean a serious?','illness','shopping center','manufacturing process','illness','malady.s1 指疾病。'),Q('malady',2,2,'A social malady is?','a serious problem affecting society','a harmless personal preference','a type of cosmetics','a serious problem affecting society','malady.s2 可比喻社会弊病。'),Q('malady',3,1,'Which issue might be called a social malady?','widespread corruption damaging public services','one person forgetting a small umbrella','a store changing its logo','widespread corruption damaging public services','广泛腐败造成系统性损害，可比喻为社会弊病。'),Q('malady',4,1,'Malady is a relatively?','formal or literary word','technical term for a mall','verb meaning to manufacture','formal or literary word','malady 常见于正式或文学语境。','register')]});
D('malaria',{etymology:E('Malaria was borrowed from Italian mala aria, “bad air,” an old explanation for the disease; the illness is actually caused by Plasmodium parasites transmitted by Anopheles mosquitoes.','malaria'),contexts:[C('malaria.s1','公共卫生','The clinic tested the returning traveler for malaria after he developed recurrent fever and chills.','这名返乡旅客出现反复发热和寒战后，诊所为他进行了疟疾检测。','The clinic tested the returning traveler / for malaria / after he developed / recurrent fever and chills.','malaria 是由按蚊传播寄生虫引起的感染性疾病。','反复发热和寒战促使医生检测疟疾。')],mistakes:[M('The traveler’s malaria was caused by drinking cold water, and mosquitoes played no part in transmission.','Malaria can be transmitted when an infected Anopheles mosquito bites a person.','疟疾由寄生虫感染引起，按蚊传播；冷水饮用不是病因。')],quiz:[Q('malaria',1,1,'Malaria is an infectious disease transmitted by?','Anopheles mosquitoes','house cats only','shopping carts','Anopheles mosquitoes','malaria.s1 是经按蚊传播的感染性疾病。'),Q('malaria',2,1,'Recurring fever and chills may lead a clinician to test for?','malaria','makeup','malignity','malaria','反复发热和寒战可促使医生检测疟疾。'),Q('malaria',3,1,'Malaria is caused by?','Plasmodium parasites','cold air alone','a harmless cosmetic','Plasmodium parasites','疟疾由疟原虫引起。'),Q('malaria',4,1,'Which prevention step can reduce malaria risk?','avoiding Anopheles mosquito bites','sharing makeup brushes','standing in a shopping mall','avoiding Anopheles mosquito bites','避免按蚊叮咬有助于降低感染风险。')]});
D('Malaysia',{etymology:E('Malaysia is a modern country name formed from Malay and the place-name suffix -sia; it names a Southeast Asian country whose capital is Kuala Lumpur.','malaysia'),contexts:[C('Malaysia.s1','地理课程','Malaysia includes territories on the Malay Peninsula and on the island of Borneo.','马来西亚的领土包括马来半岛以及婆罗洲岛上的地区。','Malaysia includes territories / on the Malay Peninsula / and / on the island of Borneo.','Malaysia 指东南亚国家马来西亚。','句子描述该国分布于马来半岛和婆罗洲。')],mistakes:[M('The atlas placed Malaysia in northern Europe and named Oslo as its capital.','The atlas placed Malaysia in Southeast Asia and identified Kuala Lumpur as its capital.','马来西亚位于东南亚，首都为吉隆坡，不在欧洲。')],quiz:[Q('Malaysia',1,1,'Malaysia is in?','Southeast Asia','South America','northern Europe','Southeast Asia','Malaysia.s1 是东南亚国家。'),Q('Malaysia',2,1,'The capital of Malaysia is?','Kuala Lumpur','Manila','Jakarta','Kuala Lumpur','马来西亚首都是吉隆坡。'),Q('Malaysia',3,1,'Malaysia has territory on?','the Malay Peninsula and Borneo','Greenland and Iceland','the Iberian Peninsula only','the Malay Peninsula and Borneo','马来西亚领土位于马来半岛和婆罗洲。'),Q('Malaysia',4,1,'Malaysia is a?','country','city in Scotland','disease','country','Malaysia 是一个国家。')]});
D('malcontent',{etymology:E('Malcontent combines French mal “badly” and content “satisfied”; it can describe a dissatisfied person or that person’s discontented attitude.','malcontent'),contexts:[C('malcontent.s2','职场讨论','The malcontent in the department complained about every policy but offered no practical alternative.','部门里那位牢骚者对每项政策都抱怨，却拿不出可行的替代方案。','The malcontent in the department / complained about every policy / but offered / no practical alternative.','malcontent.s2 作名词，指总对现状不满、爱发牢骚的人。','这个人不断抱怨现状。')],mistakes:[M('The malcontent praised every change, expressed complete satisfaction, and never complained about the situation.','The malcontent voiced dissatisfaction with the changes and urged the team to reconsider them.','始终满意、不抱怨与 malcontent 的特点相反。')],quiz:[Q('malcontent',1,1,'A malcontent person is?','dissatisfied with the present situation','fully pleased with every decision','a skilled manufacturer','dissatisfied with the present situation','malcontent.s1 表示不满的。'),Q('malcontent',2,2,'A malcontent is?','a person who is often unhappy and complains','a person who builds shopping centers','a person with malaria','a person who is often unhappy and complains','malcontent.s2 指不满现状者。'),Q('malcontent',3,1,'Which person might be called a malcontent?','someone who constantly grumbles about the organization','someone who approves every change without complaint','someone who manages production calmly','someone who constantly grumbles about the organization','持续牢骚抱怨的人符合该词义。'),Q('malcontent',4,1,'Malcontent combines mal- with an idea of being?','satisfied','manufactured','male','satisfied','content 表示满意，malcontent 表示不满意。','word-formation')]});
D('male',{etymology:E('Male comes through Old French from Latin masculus; it describes the sex that produces sperm in humans and many animals, and can be a noun for a boy, man, or male animal.','male'),contexts:[C('male.s1','生物学观察','The researchers marked each male turtle and released it after recording its shell length.','研究人员给每只雄性海龟做了标记，记录甲壳长度后便将其放归。','The researchers marked each male turtle / and released it / after recording / its shell length.','male.s1 作形容词，表示男性或雄性的。','这里 male 修饰 turtle，指其生物学性别。')],mistakes:[M('The field notes called the female turtle male even though its sex had been confirmed as female.','The field notes called the turtle male after the researchers identified it as a male.','已确认是雌性就不能称 male。')],quiz:[Q('male',1,1,'A male animal belongs to the sex that?','produces sperm','lays every egg','is always larger','produces sperm','male.s1 描述雄性。'),Q('male',2,2,'A male may also refer to?','a male person or animal','only a company that makes products','a serious illness','a male person or animal','male.s2 作名词指男性或雄性动物。'),Q('male',3,1,'Which phrase uses male as an adjective?','a male deer','a male is standing there','malevolent deer','a male deer','male 修饰 deer，作形容词。','grammar'),Q('male',4,1,'Male is often contrasted with?','female','malaria','malleable','female','male 与 female 相对。','confusable')]});
D('malediction',{etymology:E('Malediction comes from Latin maledictio, from male “badly” and dicere “to speak”; it means a curse or words calling evil down on someone.','malediction'),contexts:[C('malediction.s1','文学翻译','The sorcerer’s malediction promised misfortune to anyone who opened the sealed tomb.','巫师的诅咒称，任何打开封墓的人都会遭遇不幸。','The sorcerer’s malediction / promised misfortune / to anyone / who opened the sealed tomb.','malediction 指诅咒、咒骂或祈愿他人遭受灾祸的话语。','咒语明确呼唤厄运降临。')],mistakes:[M('The character’s blessing was a malediction because it wished the traveler health, safety, and good fortune.','The character’s malediction wished sickness and misfortune on the traveler.','祝愿健康和好运与诅咒相反。')],quiz:[Q('malediction',1,1,'A malediction is a?','curse','compliment','shopping center','curse','malediction.s1 指诅咒。'),Q('malediction',2,1,'A character might utter a malediction to?','call misfortune down on an enemy','wish a rival good luck','describe a medical symptom','call misfortune down on an enemy','诅咒是祈愿对方遭受不幸。'),Q('malediction',3,1,'Malediction is closest to?','curse','blessing','management','curse','curse 和 malediction 意思接近。','meaning'),Q('malediction',4,1,'The Latin roots point to “speaking”?','badly','carefully','quietly','badly','male- 带有“坏地”之意，dicere 是说。','word-formation')]});
D('malevolence',{etymology:E('Malevolence comes from Latin malevolentia, from male “badly” and velle “to wish”; it is the quality of wanting harm or suffering to come to others.','malevolence'),contexts:[C('malevolence.s1','人物动机','The investigator found no evidence of malevolence; the damage appeared to result from a careless mistake.','调查人员没有发现恶意证据；损坏似乎源于一次粗心失误。','The investigator found no evidence / of malevolence / the damage appeared / to result from a careless mistake.','malevolence 指希望他人受到伤害的恶意。','故意伤害与意外疏忽不同，调查未发现前者。')],mistakes:[M('The review accused her of malevolence even though she had tried to protect everyone and caused no harm intentionally.','The review found malevolence when messages showed she deliberately wanted her rival to suffer.','无意造成的损害不能证明希望他人受苦。')],quiz:[Q('malevolence',1,1,'Malevolence is?','the desire to harm others','an ability to manage a team','a serious tropical disease','the desire to harm others','malevolence.s1 指恶意。'),Q('malevolence',2,1,'A person acting with malevolence?','wants someone else to suffer','makes an accidental mistake only','is trying to help a rival','wants someone else to suffer','恶意行为包含伤害他人的意图。'),Q('malevolence',3,1,'Which is evidence of malevolence?','a message expressing a deliberate wish to injure someone','a note apologizing for an accidental spill','a neutral report of a measurement','a message expressing a deliberate wish to injure someone','主动表达伤害意图可体现恶意。'),Q('malevolence',4,1,'Malevolence is the noun related to?','malevolent','manageable','Malaysia','malevolent','malevolence 是 malevolent 对应的名词。','word-formation')]});
D('malevolent',{etymology:E('Malevolent comes from Latin malevolent-, from male “badly” and velle “to wish”; it describes someone wishing harm or words and looks that show such hatred.','malevolent'),contexts:[C('malevolent.s2','戏剧表演','The actor gave the rival a malevolent stare that made the audience expect another act of sabotage.','演员投向对手一个恶毒的眼神，让观众预感又一次破坏行动即将发生。','The actor gave the rival / a malevolent stare / that made the audience expect / another act of sabotage.','malevolent.s2 描写目光、言语或力量流露出仇恨与恶意。','眼神传达强烈敌意，并预示有害行动。')],mistakes:[M('The smile was malevolent even though it conveyed sincere warmth and a wish for the stranger’s success.','The malevolent stare conveyed hatred and a wish to harm the rival.','真诚祝愿对方成功不是恶毒的神情。')],quiz:[Q('malevolent',1,1,'A malevolent person wishes?','harm to others','success for everyone','a long life','harm to others','malevolent.s1 指怀有恶意的。'),Q('malevolent',2,2,'A malevolent look shows?','hatred or hostility','tiredness only','a makeup style','hatred or hostility','malevolent.s2 可形容流露仇恨的眼神。'),Q('malevolent',3,1,'Which behavior is malevolent?','deliberately trying to ruin a colleague’s work','quietly correcting a harmless typo','offering a sincere apology','deliberately trying to ruin a colleague’s work','故意破坏同事工作体现恶意。'),Q('malevolent',4,1,'Malevolent is an adjective related to the noun?','malevolence','malediction','malady','malevolence','malevolent 对应 malevolence。','word-formation')]});
D('malfunction',{etymology:E('Malfunction combines mal- “badly” with function; as a noun or verb it describes a failure to work properly.','malfunction'),contexts:[C('malfunction.s1','设备检修','A sensor malfunction shut down the heating system, so technicians replaced the faulty unit.','传感器故障使供暖系统停机，因此技术人员更换了失灵部件。','A sensor malfunction / shut down the heating system / so technicians replaced / the faulty unit.','malfunction.s1 可作名词指故障，也可作动词表示发生故障。','设备未正常工作，检修人员更换了故障部件。')],mistakes:[M('The printer malfunctioned by completing every job accurately and operating exactly as designed.','The printer malfunctioned when it repeatedly jammed during normal use.','正常工作不能称为 malfunction。')],quiz:[Q('malfunction',1,1,'A malfunction is?','a failure to work normally','a person who makes products','a strong desire for harm','a failure to work normally','malfunction.s1 作名词指故障。'),Q('malfunction',2,1,'If a device malfunctions, it?','fails to work properly','is manufactured successfully','is made temporarily available','fails to work properly','malfunction 作动词表示失灵。'),Q('malfunction',3,1,'Which is a malfunction?','an alarm that sounds without a fire','an alarm that works as designed','a sign showing the exit','an alarm that sounds without a fire','误报可能说明警报器发生故障。'),Q('malfunction',4,1,'Malfunction combines function with a prefix meaning?','badly or incorrectly','very slowly','not at all ever','badly or incorrectly','mal- 表示坏或不良。','word-formation')]});
D('malice',{etymology:E('Malice comes from Latin malitia, “badness”; it means a desire to hurt someone or, in legal contexts, an intention to do wrong.','malice'),contexts:[C('malice.s2','法律审查','The prosecutor had to show malice by proving that the defendant acted with an intention to cause harm.','检察官必须通过证明被告有意造成伤害来证明其恶意。','The prosecutor had to show malice / by proving / that the defendant acted / with an intention to cause harm.','malice.s2 在法律语境中可指故意做错事或造成伤害的意图。','检方需要证明行为人具有伤害意图。')],mistakes:[M('The report found malice in an entirely accidental collision with no evidence that either driver intended harm.','The report found malice after messages showed the driver deliberately aimed at the other car.','纯属意外且无伤害意图不足以证明恶意。')],quiz:[Q('malice',1,1,'Malice is a desire to?','hurt someone','help a stranger','manufacture a product','hurt someone','malice.s1 指伤害他人的恶意。'),Q('malice',2,2,'In law, malice may involve?','an intention to do wrong','a temporary makeup test','a harmless technical failure','an intention to do wrong','malice.s2 可指违法或伤害的故意。'),Q('malice',3,1,'Which action suggests malice?','deliberately damaging a neighbor’s car out of spite','accidentally spilling water and apologizing','repairing a broken shared fence','deliberately damaging a neighbor’s car out of spite','故意出于怨恨损坏财物表明恶意。'),Q('malice',4,1,'Malice contrasts with?','goodwill','malfunction','malaria','goodwill','goodwill 表示善意，与 malice 相反。','confusable')]});
D('malicious',{etymology:E('Malicious comes from Old French malicios, ultimately from Latin malitia “badness”; it describes an intention to harm another person.','malicious'),contexts:[C('malicious.s1','网络安全','The malicious message contained a link designed to steal the recipient’s passwords.','这条恶意信息包含一个旨在窃取收件人密码的链接。','The malicious message contained a link / designed to steal / the recipient’s passwords.','malicious 指有意伤害他人或造成损害的。','链接被设计用于窃取密码，具有明确伤害意图。')],mistakes:[M('The security team called the harmless reminder malicious even though it contained no threat, deception, or harmful intent.','The security team called the password-stealing link malicious because it was designed to harm users.','无害提醒没有恶意目的，窃取密码的链接则有伤害意图。')],quiz:[Q('malicious',1,1,'A malicious act is intended to?','harm someone','offer help','measure a distance','harm someone','malicious.s1 指蓄意伤害的。'),Q('malicious',2,1,'Which message is malicious?','a fake alert designed to steal account passwords','a genuine reminder about a meeting','a sincere apology for a late reply','a fake alert designed to steal account passwords','欺骗用户窃取密码的消息有恶意。'),Q('malicious',3,1,'Malicious is closest in meaning to?','spiteful','helpful','careless only','spiteful','spiteful 含有恶意、怀恨的意味。','meaning'),Q('malicious',4,1,'A malicious rumor is spread?','with an intention to damage someone','to correct a verified mistake','without any words','with an intention to damage someone','恶意谣言旨在损害他人。')]});
D('malign',{etymology:E('Malign comes from Latin malignus, “bad-natured”; as an adjective it means harmful or ill-disposed, and as a verb it means make damaging and untrue claims about someone.','malign'),contexts:[C('malign.s2','媒体报道','The columnist was sued for maligning the doctor with claims that records later showed were false.','专栏作者因诋毁医生而被起诉，相关说法后来被证明是虚假的。','The columnist was sued / for maligning the doctor / with claims / that records later showed were false.','malign.s2 作动词，指说有害且不实的话来诋毁某人。','这些不实指控损害了医生的名誉。')],mistakes:[M('The columnist maligned the doctor by publishing a verified, accurate account that praised the doctor’s work.','The columnist maligned the doctor by publishing false accusations intended to damage the doctor’s reputation.','准确赞扬并非诋毁；malign 作动词含有有害不实陈述。')],quiz:[Q('malign',1,1,'A malign influence is?','harmful','beneficial','temporary makeup','harmful','malign.s1 可作形容词表示有害的。'),Q('malign',2,2,'To malign a person is to?','make damaging and untrue claims about them','praise them with accurate evidence','manufacture a product for them','make damaging and untrue claims about them','malign.s2 作动词指诋毁。'),Q('malign',3,1,'Which is maligning someone?','spreading a false accusation to damage their reputation','quoting a verified award citation','asking them a neutral question','spreading a false accusation to damage their reputation','有害的不实指控构成诋毁。'),Q('malign',4,1,'Malign as a verb usually has a?','harmful reputational effect','medical meaning of a tumor','meaning of a shopping arcade','harmful reputational effect','动词 malign 指损害名誉的诋毁。')]});
D('malignant',{etymology:E('Malignant comes from Latin malignans, “acting maliciously”; medically it describes a cancerous tumor that can grow and spread, and more generally it can mean malicious or hostile.','malignant'),contexts:[C('malignant.s1','病理诊断','The biopsy showed that the tumor was malignant, so the oncology team discussed treatment options promptly.','活检显示肿瘤为恶性，因此肿瘤科团队及时讨论了治疗方案。','The biopsy showed / that the tumor was malignant / so the oncology team / discussed treatment options promptly.','malignant.s1 医学上指能够生长、扩散并可能致命的恶性肿瘤。','活检结果提示恶性肿瘤，需要及时讨论治疗。')],mistakes:[M('The biopsy called the tumor malignant even though the cells were benign and showed no invasive growth.','The biopsy identified the tumor as malignant after finding cancerous cells able to spread.','良性且不侵袭的肿瘤不符合 malignant 的医学义。')],quiz:[Q('malignant',1,1,'A malignant tumor is one that can?','grow and spread as cancer','never invade nearby tissue','only change a person’s makeup','grow and spread as cancer','malignant.s1 指恶性肿瘤。'),Q('malignant',2,2,'A malignant remark may be?','hostile and intended to harm','kind and encouraging','a formal medical test','hostile and intended to harm','malignant.s2 也可形容恶毒敌意的言行。'),Q('malignant',3,1,'A malignant tumor contrasts with a?','benign tumor','shopping mall','makeshift repair','benign tumor','benign 与 malignant 在肿瘤性质上相对。','confusable'),Q('malignant',4,1,'Which professional is most likely to discuss a malignant tumor?','an oncologist','a mall security guard','a furniture maker','an oncologist','肿瘤科医生处理恶性肿瘤。')]});
D('malignity',{etymology:E('Malignity is formed from malign with -ity; it names deep malevolence or a strongly harmful and hostile disposition.','malignity'),contexts:[C('malignity.s1','文学评论','The villain’s malignity became clear when he admitted that he had arranged the fire to frighten the villagers.','反派承认纵火是为了恐吓村民后，他的恶毒本性便显露出来。','The villain’s malignity became clear / when he admitted / that he had arranged the fire / to frighten the villagers.','malignity 指深重的恶意或伤害他人的恶毒倾向。','人物蓄意纵火并以恐吓他人为目的。')],mistakes:[M('The character’s malignity was evident because he rescued the villagers and risked his life to protect them.','The character’s malignity was evident because he deliberately endangered the villagers.','冒险保护他人与深重恶意相反。')],quiz:[Q('malignity',1,1,'Malignity is?','deep malevolence','a temporary illness','a person who makes furniture','deep malevolence','malignity.s1 指歹意。'),Q('malignity',2,1,'A character’s malignity might be shown by?','deliberately harming innocent people','quietly repairing a public bench','giving accurate medical advice','deliberately harming innocent people','蓄意伤害无辜者体现恶毒。'),Q('malignity',3,1,'Malignity is the noun related to?','malign','manageable','mammal','malign','malignity 由 malign 加 -ity 构成。','word-formation'),Q('malignity',4,1,'Malignity most strongly contrasts with?','benevolence','malice','malevolence','benevolence','benevolence 指善意，与 malignity 相反。','confusable')]});
D('mall',{etymology:E('Mall was shortened from Pall Mall, a 17th-century game and London street name; today it commonly means a large covered shopping center, and historically a public walk.','mall'),contexts:[C('mall.s1','城市商业','The new mall includes a grocery store, a library branch, and several small clothing shops.','这座新购物中心里有一家杂货店、一间图书馆分馆和几家小型服装店。','The new mall includes / a grocery store, a library branch, / and several small clothing shops.','mall.s1 指有许多商店的大型室内购物区。','多家商店集中在一处大型商业空间。')],mistakes:[M('The neighborhood called its small private bedroom a mall even though no shops or public shopping space existed there.','The neighborhood called the covered complex with many stores a mall.','私人卧室不是购物中心。')],quiz:[Q('mall',1,1,'A shopping mall contains?','many shops in a large covered area','a single private bedroom','a medical diagnosis','many shops in a large covered area','mall.s1 指购物中心。'),Q('mall',2,2,'Historically, a mall could also be?','a wide public walk','a tumor','a person who complains','a wide public walk','mall.s2 有林荫大道或步行大街的历史义。'),Q('mall',3,1,'Where might someone shop for clothes and groceries in one complex?','at a mall','in a malediction','on a mandible','at a mall','大型购物中心可集中多种商店。'),Q('mall',4,1,'Which phrase is natural?','a covered shopping mall','a mall of malaria','a mall to the tumor','a covered shopping mall','covered shopping mall 是自然搭配。','collocation')]});
D('malleability',{etymology:E('Malleability is formed from malleable with -ity; it describes a material’s ability to be shaped or a person or plan’s susceptibility to change.','malleability'),contexts:[C('malleability.s1','材料科学','The gold’s malleability allowed the artisan to press it into a thin decorative leaf without cracking it.','黄金的延展性使工匠能够把它压成薄薄的装饰金箔而不使其开裂。','The gold’s malleability allowed the artisan / to press it into / a thin decorative leaf / without cracking it.','malleability.s1 指金属可被压制成形的能力，也可指人或计划易受改变。','黄金经压制仍能保持完整并变薄。')],mistakes:[M('The metal’s malleability meant it shattered into pieces as soon as the artisan tried to flatten it.','The metal’s malleability let the artisan flatten and shape it without breaking.','易碎裂与可锻性相反。')],quiz:[Q('malleability',1,1,'A metal’s malleability is its ability to?','be shaped without breaking','resist every attempt to shape it','rust instantly in dry air','be shaped without breaking','malleability.s1 指可锻性。'),Q('malleability',2,1,'A person’s malleability may refer to being?','open to influence or change','physically made of metal','unable to learn anything','open to influence or change','malleability 也可比喻易受影响、可塑。'),Q('malleability',3,1,'Which material property would help make thin foil?','malleability','malnutrition','malice','malleability','金属可锻性有助于压成薄片。'),Q('malleability',4,1,'Malleability is the noun related to?','malleable','malicious','manageable','malleable','malleability 由 malleable 派生。','word-formation')]});
D('malleable',{etymology:E('Malleable comes through Old French from Latin malleus “hammer”; it describes metal that can be shaped by pressing or a person or plan that can be influenced.','malleable'),contexts:[C('malleable.s2','教育心理','Young children’s views can be malleable, so adults should help them evaluate claims rather than simply repeat them.','年幼儿童的观点容易受到影响，因此成年人应帮助他们评估说法，而不只是让他们照搬。','Young children’s views can be malleable / so adults should help them evaluate claims / rather than / simply repeat them.','malleable.s2 比喻容易被影响、训练或改变的。','教育者引导孩子判断信息，而不是让观点被动定型。')],mistakes:[M('The clay was malleable because it could not be pressed, bent, or changed into another shape.','The clay was malleable because the potter could press it into a new shape.','无法塑形的材料不具可塑性。')],quiz:[Q('malleable',1,1,'Malleable metal can be?','shaped by pressing or hammering','changed only by being eaten','never altered without shattering','shaped by pressing or hammering','malleable.s1 指可锻的。'),Q('malleable',2,2,'A malleable attitude is?','open to influence or change','fixed and impossible to affect','a kind of wooden hammer','open to influence or change','malleable.s2 指易受影响的。'),Q('malleable',3,1,'Which substance is most likely malleable?','soft gold that can be pressed into a sheet','dry glass that shatters under pressure','a sealed brick wall','soft gold that can be pressed into a sheet','黄金可以压成薄片，体现可锻性。'),Q('malleable',4,1,'Malleable is related to the noun?','malleability','malady','maltreatment','malleability','malleability 是 malleable 的名词形式。','word-formation')]});
D('mallet',{etymology:E('Mallet comes from French maillet, a diminutive of mail “hammer”; it is a hammer with a wooden head, used for striking without the hardness of metal.','mallet'),contexts:[C('mallet.s1','木工操作','The carpenter tapped the fitted joint with a wooden mallet so the pieces would seat without denting the surface.','木匠用木槌轻敲接合处，使部件嵌合而不压出凹痕。','The carpenter tapped the fitted joint / with a wooden mallet / so the pieces would seat / without denting the surface.','mallet.s1 指木头制成锤头的槌子。','木槌可施力而不容易损坏木材表面。')],mistakes:[M('The craft worker struck the delicate wood with a steel sledgehammer and called the tool a mallet.','The craft worker used a wooden mallet to tap the delicate joint into place.','mallet 的锤头是木制的，不是钢制大锤。')],quiz:[Q('mallet',1,1,'A mallet is a hammer with a?','wooden head','rubber rope','stone handle only','wooden head','mallet.s1 指木槌。'),Q('mallet',2,1,'A carpenter might use a mallet to?','tap a joint without denting it','cut down an entire tree','measure a longitude','tap a joint without denting it','木槌适合轻敲木制接合处。'),Q('mallet',3,1,'Which tool is a mallet?','a wooden-headed hammer','a small medical tumor','a shopping arcade','a wooden-headed hammer','木头锤头的锤子是 mallet。'),Q('mallet',4,1,'Mallet is a kind of?','hammer','disease','animal','hammer','mallet 属于锤子。')]});
D('malnourished',{etymology:E('Malnourished combines mal- “badly” with nourished; it describes a person or animal weakened or growing poorly because of inadequate or unsuitable nutrition.','malnourished'),contexts:[C('malnourished.s2','儿童健康','The aid workers referred the malnourished child for care after noticing that growth had slowed for months.','援助人员发现孩子几个月来生长迟缓后，将这名营养不良的儿童转介接受照护。','The aid workers referred / the malnourished child / for care / after noticing that growth had slowed for months.','malnourished.s2 指因营养不足或不当而发育受阻的。','长期生长迟缓提示营养问题影响了发育。')],mistakes:[M('The child was malnourished despite having adequate balanced food and healthy growth throughout the year.','The child was malnourished after prolonged inadequate nutrition led to weak growth.','充足均衡饮食和健康生长与营养不良不符。')],quiz:[Q('malnourished',1,1,'A malnourished person may be weak because of?','inadequate or poor-quality nutrition','too much sleep alone','a wooden hammer','inadequate or poor-quality nutrition','malnourished.s1 指营养不足导致虚弱。'),Q('malnourished',2,2,'A malnourished child may show?','poor growth linked to insufficient food','unusually rapid healthy growth from balanced meals','a shopping center in the body','poor growth linked to insufficient food','malnourished.s2 可描述发育受阻。'),Q('malnourished',3,1,'Which situation may lead to malnourishment?','lacking enough nutritious food over time','having regular balanced meals','receiving adequate nourishment','lacking enough nutritious food over time','长期缺少营养食物可能导致营养不良。'),Q('malnourished',4,1,'Malnourished contains a prefix meaning?','badly or inadequately','very quickly','in a male way','badly or inadequately','mal- 表示不良或不足。','word-formation')]});
D('malnutrition',{etymology:E('Malnutrition combines mal- “badly” with nutrition; it means poor health from too little food or an unbalanced diet that lacks or overprovides needed nutrients.','malnutrition'),contexts:[C('malnutrition.s2','营养评估','The survey found malnutrition among children whose diets contained too few essential nutrients, despite sufficient calories.','调查发现，一些儿童虽然摄入热量足够，但饮食缺少必需营养素，仍存在营养失调。','The survey found malnutrition / among children / whose diets contained too few essential nutrients / despite sufficient calories.','malnutrition.s2 可指营养失调，既包括不足，也包括饮食不均衡。','有足够热量却缺乏必需营养素仍可能营养失调。')],mistakes:[M('The clinician ruled out malnutrition solely because the patient ate enough calories, without considering whether the diet lacked essential nutrients.','The clinician assessed malnutrition by checking both calorie intake and the balance of nutrients.','热量充足并不排除营养失调。')],quiz:[Q('malnutrition',1,1,'Malnutrition can result from?','too little food or an unbalanced diet','using a wooden mallet','living in Malaysia','too little food or an unbalanced diet','malnutrition.s1 指营养不足造成的健康问题。'),Q('malnutrition',2,2,'A diet with enough calories but too few essential nutrients may cause?','malnutrition','malice','malfunction','malnutrition','malnutrition.s2 包括营养不均衡。'),Q('malnutrition',3,1,'Which case may involve malnutrition?','a person eating enough but missing key nutrients','a person with a balanced varied diet','a metal that can be shaped','a person eating enough but missing key nutrients','热量足够但营养素失衡也会营养不良。'),Q('malnutrition',4,1,'Malnutrition is related to?','nutrition','management','maneuver','nutrition','malnutrition 由 mal- 和 nutrition 构成。','word-formation')]});
D('malpractice',{etymology:E('Malpractice combines mal- “badly” and practice; it means improper professional conduct, especially a failure by a doctor or lawyer to meet the required standard of care.','malpractice'),contexts:[C('malpractice.s2','职业审查','The auditor uncovered malpractice when a public official secretly awarded contracts to a company owned by a relative.','审计人员发现一名公职人员暗中把合同授予亲属拥有的公司，构成舞弊渎职。','The auditor uncovered malpractice / when a public official secretly awarded contracts / to a company / owned by a relative.','malpractice.s2 指公职或职业角色中的不当、不诚实行为。','公职人员利用职权偏袒亲属公司。')],mistakes:[M('The report called the official’s transparent, rule-compliant procurement malpractice despite finding no misconduct or dishonesty.','The report called the secret biased contract awards official malpractice.','遵守规则且透明的行为不是渎职。')],quiz:[Q('malpractice',1,1,'Medical malpractice involves?','a professional’s failure to provide proper care','a temporary substitute bridge','a nutritional deficiency only','a professional’s failure to provide proper care','malpractice.s1 指医疗或法律过失。'),Q('malpractice',2,2,'Official malpractice may include?','dishonest conduct in a professional role','a harmless makeup test','a mammal’s normal growth','dishonest conduct in a professional role','malpractice.s2 指职务舞弊或渎职。'),Q('malpractice',3,1,'Which case suggests malpractice?','a lawyer mishandles a case by ignoring required duties','a doctor follows the accepted procedure carefully','an official discloses a conflict and recuses herself','a lawyer mishandles a case by ignoring required duties','违反职业职责可能构成 malpractice。'),Q('malpractice',4,1,'Malpractice is most closely associated with?','professional misconduct','shopping','animal classification','professional misconduct','malpractice 指职业失当行为。')]});
D('malt',{etymology:E('Malt comes from Old English mealt; it is grain, commonly barley, that has sprouted and then been dried, and the verb means process grain in this way.','malt'),contexts:[C('malt.s1','酿造工艺','The brewer soaked the barley, allowed it to sprout, and dried it to produce malt for the next batch.','酿酒师浸泡大麦，让它发芽后再烘干，为下一批酿造制成麦芽。','The brewer soaked the barley / allowed it to sprout / and dried it / to produce malt for the next batch.','malt.s1 指发芽后再干燥的谷物，常为大麦。','工艺包括浸泡、发芽和干燥。')],mistakes:[M('The brewer called raw, unsprouted, undried barley malt before any malting process had taken place.','The brewer called the sprouted and dried barley malt.','未发芽、未干燥的谷物尚未制成麦芽。')],quiz:[Q('malt',1,1,'Malt is commonly made from barley that has?','sprouted and then been dried','been frozen while still growing','been ground into flour before sprouting','sprouted and then been dried','malt.s1 指发芽后干燥的谷物。'),Q('malt',2,2,'To malt grain is to?','convert it through sprouting and drying','turn it into a wooden mallet','store it in a shopping mall','convert it through sprouting and drying','malt.s2 作动词表示制麦芽。'),Q('malt',3,1,'A brewer may use malt to?','make a fermented drink','treat a broken wrist','manage a clinic','make a fermented drink','麦芽常用于酿造饮品。'),Q('malt',4,1,'Malt is a processed form of?','grain','metal','mammal','grain','malt 由谷物加工而来。')]});
D('maltreat',{etymology:E('Maltreat combines mal- “badly” with treat; it means treat someone cruelly or violently, especially someone in one’s care.','maltreat'),contexts:[C('maltreat.s1','动物福利','The shelter investigated whether the animals had been maltreated before they were brought in.','收容所调查这些动物在被送来之前是否遭受过虐待。','The shelter investigated / whether the animals had been maltreated / before they were brought in.','maltreat 指残忍或暴力地对待需要照护的人或动物。','调查关注动物此前是否遭受了不当伤害。')],mistakes:[M('The owner maltreated the dog by providing safe shelter, proper food, and gentle veterinary care.','The owner maltreated the dog by striking it and withholding necessary care.','提供妥善照护与虐待相反。')],quiz:[Q('maltreat',1,1,'To maltreat an animal is to?','treat it cruelly','feed it responsibly','train it gently','treat it cruelly','maltreat.s1 指虐待。'),Q('maltreat',2,1,'Which action is maltreatment?','violently harming someone in your care','providing appropriate medical attention','offering food and a safe home','violently harming someone in your care','对被照护者施暴属于虐待。'),Q('maltreat',3,1,'Maltreat combines treat with a prefix meaning?','badly','together','before','badly','mal- 表示不良地。','word-formation'),Q('maltreat',4,1,'Maltreat is a verb describing?','cruel treatment','professional management','grain processing','cruel treatment','maltreat 表示残忍地对待。')]});
D('maltreatment',{etymology:E('Maltreatment is formed from maltreat with the noun suffix -ment; it names cruel or harmful treatment of a person or animal.','maltreatment'),contexts:[C('maltreatment.s1','儿童保护','The social worker documented signs of maltreatment and arranged a safe placement while the case was reviewed.','社工记录了虐待迹象，并在案件审查期间安排了安全安置。','The social worker documented / signs of maltreatment / and arranged a safe placement / while the case was reviewed.','maltreatment 指残忍或有害地对待某人或动物的行为。','社工记录伤害迹象并采取保护措施。')],mistakes:[M('The report described maltreatment even though the caregiver consistently provided safe, respectful, and attentive care.','The report documented maltreatment after finding repeated injuries and deliberate neglect.','妥善照护并不能证明虐待。')],quiz:[Q('maltreatment',1,1,'Maltreatment means?','cruel or harmful treatment','a method of drying grain','a shopping complex','cruel or harmful treatment','maltreatment.s1 指虐待行为。'),Q('maltreatment',2,1,'A caseworker investigates maltreatment to determine whether?','someone was treated cruelly or harmed','a wooden mallet was purchased','a new mall will be built','someone was treated cruelly or harmed','调查虐待是判断是否有人受到残忍对待。'),Q('maltreatment',3,1,'Maltreatment is the noun related to?','maltreat','malleable','manage','maltreat','maltreatment 由 maltreat 加 -ment 构成。','word-formation'),Q('maltreatment',4,1,'Which phrase is natural?','reports of child maltreatment','maltreatment the barley to make malt','maltreatment of a business manager as a job title','reports of child maltreatment','child maltreatment 是自然搭配。','collocation')]});
D('malware',{etymology:E('Malware blends malicious and software; it names software designed to damage, disrupt, or gain unauthorized access to a computer system.','malware'),contexts:[C('malware.s1','网络防护','The security update removed malware that had been secretly collecting keystrokes on the office computers.','安全更新清除了恶意软件；该软件曾秘密记录办公室电脑上的击键。','The security update removed malware / that had been secretly collecting keystrokes / on the office computers.','malware 指旨在损害、干扰或未经许可访问系统的软件。','程序秘密收集输入信息，具有恶意用途。')],mistakes:[M('The technician called a harmless calculator app malware even though it collected no data, caused no damage, and requested no access.','The technician identified the hidden password-stealing program as malware.','无害应用不符合恶意软件的用途特征。')],quiz:[Q('malware',1,1,'Malware is software designed to?','harm or compromise a computer system','improve a user’s typing skills only','make a temporary bridge','harm or compromise a computer system','malware.s1 指恶意软件。'),Q('malware',2,1,'A program that secretly steals passwords is?','malware','malt','mammalian','malware','窃取密码的恶意程序属于 malware。'),Q('malware',3,1,'Malware is a blend of malicious and?','software','hardware','manure','software','malware 由 malicious 与 software 混成。','word-formation'),Q('malware',4,1,'Which step can help prevent malware infection?','keeping security software updated','opening every unknown attachment','sharing passwords publicly','keeping security software updated','更新安全软件有助于降低恶意软件风险。')]});
D('mammal',{etymology:E('Mammal derives from Latin mamma “breast”; it names an animal whose young are fed with milk, and the class Mammalia that includes humans and whales.','mammal'),contexts:[C('mammal.s1','自然科学','The bat is a mammal: it gives birth to live young and feeds them milk.','蝙蝠是哺乳动物：它生下幼崽并用乳汁喂养它们。','The bat is a mammal / it gives birth to live young / and feeds them / milk.','mammal.s1 指以乳汁哺育幼体的温血动物。','蝙蝠具有哺乳动物的繁殖和哺育特征。')],mistakes:[M('The bat was classified as a mammal because it laid eggs and never fed its young milk.','The bat was classified as a mammal because it feeds its young with milk.','哺乳动物的典型特征包括以乳汁喂养幼体。')],quiz:[Q('mammal',1,1,'A mammal feeds its young with?','milk','malt','wood pulp','milk','mammal.s1 指哺乳动物。'),Q('mammal',2,2,'Mammal can also name?','the animal class including humans and whales','a single baby tooth','a shopping district','the animal class including humans and whales','mammal.s2 可指哺乳类这一动物类群。'),Q('mammal',3,1,'Which is a mammal?','a dolphin','a trout','a lizard','a dolphin','海豚是哺乳动物。'),Q('mammal',4,1,'A mammal is generally warm-blooded and?','nurses its young','has feathers','breathes only underwater','nurses its young','哺乳动物用乳汁哺育幼体。')]});
D('mammalian',{etymology:E('Mammalian is formed from Mammalia with -an; as an adjective it means belonging to mammals, and as a noun it can refer to an individual mammal.','mammalian'),contexts:[C('mammalian.s1','动物生理','The research examined mammalian hearing and compared the range of frequencies detected by bats and mice.','这项研究考察了哺乳动物的听觉，并比较蝙蝠和老鼠所能感知的频率范围。','The research examined mammalian hearing / and compared / the range of frequencies / detected by bats and mice.','mammalian.s1 作形容词，表示哺乳类的、属于哺乳动物的。','蝙蝠和老鼠都属于哺乳动物，研究比较其听觉。')],mistakes:[M('The study called feather growth a mammalian trait even though feathers are characteristic of birds, not mammals.','The study called milk production in bats a mammalian trait.','羽毛不是哺乳动物特征。')],quiz:[Q('mammalian',1,1,'Mammalian biology studies?','mammals','only wooden tools','shopping centers','mammals','mammalian.s1 指哺乳类的。'),Q('mammalian',2,2,'In scientific writing, a mammalian may be?','an individual mammal','a type of disease','a tool for shaping metal','an individual mammal','mammalian.s2 可作名词指哺乳动物。'),Q('mammalian',3,1,'Which is a mammalian feature?','feeding young with milk','having feathers','growing from a seed','feeding young with milk','以乳汁喂养幼体是哺乳类特征。'),Q('mammalian',4,1,'Mammalian is related to the noun?','mammal','malady','mallet','mammal','mammalian 由 mammal/Mammalia 派生。','word-formation')]});
D('mammary',{etymology:E('Mammary comes from Latin mamma “breast”; it describes the milk-producing glands of mammals.','mammary'),contexts:[C('mammary.s1','医学术语','The physician explained that mammary tissue contains glands involved in producing milk.','医生解释说，乳腺组织中包含参与泌乳的腺体。','The physician explained / that mammary tissue contains glands / involved in producing / milk.','mammary 指乳房或乳腺的。','乳腺的功能与乳汁产生有关。')],mistakes:[M('The report called a salivary gland mammary even though it produces saliva rather than milk.','The report described the milk-producing breast gland as mammary tissue.','产生唾液的腺体不是乳腺。')],quiz:[Q('mammary',1,1,'Mammary glands are associated with producing?','milk','malt','malice','milk','mammary.s1 指乳腺。'),Q('mammary',2,1,'A mammary examination concerns tissue of the?','breast','jaw','hand','breast','mammary 是乳房或乳腺相关的。'),Q('mammary',3,1,'Which phrase uses mammary correctly?','mammary gland','mammary mallet','mammary shopping mall','mammary gland','mammary gland 是乳腺。','collocation'),Q('mammary',4,1,'Mammary is related to the Latin word for?','breast','hammer','management','breast','mamma 是“乳房”之意。','word-formation')]});
D('mammoth',{etymology:E('Mammoth comes from Russian mamont, the name of the extinct Ice Age elephant; by extension it describes something exceptionally large.','mammoth'),contexts:[C('mammoth.s3','城市建设','The city faces a mammoth rebuilding project after the earthquake damaged thousands of homes.','地震损毁数千套住房后，这座城市面临一项规模巨大的重建工程。','The city faces / a mammoth rebuilding project / after the earthquake / damaged thousands of homes.','mammoth.s3 作形容词，表示规模或数量极其巨大。','数千套住房受损，重建工程规模庞大。')],mistakes:[M('The team described a mammoth task as one that could be completed in a minute by a single person with no equipment.','The team described rebuilding thousands of homes as a mammoth task.','极小而轻松的工作与 mammoth 的巨大义相反。')],quiz:[Q('mammoth',1,1,'A mammoth was an extinct?','large Ice Age elephant','small modern bird','tropical disease','large Ice Age elephant','mammoth.s1 指猛犸象。'),Q('mammoth',2,2,'A mammoth project is?','extremely large','very easy and tiny','a wooden hammer','extremely large','mammoth.s3 作形容词表示巨大。'),Q('mammoth',3,3,'A mammoth can also mean?','something exceptionally large','a milk-producing gland','a shopping center','something exceptionally large','mammoth.s2 可比喻庞然大物。'),Q('mammoth',4,1,'Which is a mammoth undertaking?','rebuilding an entire city after a major disaster','changing one letter in a short note','buying a single pencil','rebuilding an entire city after a major disaster','重建整座城市规模极大。')]});
D('man',{etymology:E('Man is an old Germanic word; it can mean an adult male, humanity in older or general expressions, a person of a stated kind, or staff and operate a post or machine.','man'),contexts:[C('man.s4','设备操作','Two trained technicians will man the control room during the overnight test.','两名受过训练的技术人员将在夜间测试期间值守控制室。','Two trained technicians / will man the control room / during the overnight test.','man.s4 作动词表示为岗位或机器配备人员并负责操作。','工作人员在测试期间值守并操作控制室。')],mistakes:[M('The control room was manned even though no one was assigned to operate or monitor its equipment.','The control room was manned by trained technicians who monitored the equipment.','无人值守的控制室并未配备人员。')],quiz:[Q('man',1,1,'A man is traditionally?','an adult male human','a machine for weaving','a serious social problem','an adult male human','man.s1 指成年男子。'),Q('man',2,2,'In older phrases, man may refer broadly to?','human beings','only one company manager','a mammal’s gland','human beings','man.s2 有旧式泛指人类的用法。'),Q('man',3,3,'A “man of action” means?','a person characterized by action','only a male mechanic','a shopping mall owner','a person characterized by action','man.s3 可指某类人，未必只强调性别。'),Q('man',4,4,'To man a station is to?','staff and operate it','build it from wood','turn it into a makeshift','staff and operate it','man.s4 作动词表示为岗位配员值守。')]});
D('man-made',{etymology:E('Man-made combines man in the older general sense “human” with made; it describes something created by people rather than occurring naturally.','man-made'),contexts:[C('man-made.s1','地理环境','The reservoir is man-made; engineers built a dam to store water for nearby farms.','这个水库是人造的；工程师修建大坝，为附近农场蓄水。','The reservoir is man-made / engineers built a dam / to store water / for nearby farms.','man-made 指由人类制造或建造、而非自然形成的。','水库由工程建设而成。')],mistakes:[M('The untouched natural crater was called man-made even though no person had altered or constructed it.','The reservoir was man-made because people created it by building a dam.','未经人类建造的自然地貌不是 man-made。')],quiz:[Q('man-made',1,1,'A man-made lake was?','created by people','formed entirely without human involvement','a type of mammal','created by people','man-made.s1 指人造的。'),Q('man-made',2,1,'Which object is man-made?','a concrete bridge','a naturally formed canyon','a wildflower growing unaided','a concrete bridge','混凝土桥由人建造。'),Q('man-made',3,1,'Man-made contrasts with?','natural','manageable','malevolent','natural','man-made 与 natural 相对。','confusable'),Q('man-made',4,1,'A man-made material has been?','produced or altered by people','grown only by natural processes','left entirely untouched','produced or altered by people','此词强调人类制造。')]});
D('manacle',{etymology:E('Manacle comes from Old French manicle and Latin manicula, “little hand”; it can name a shackle for the hands or feet and the act of restraining someone with such a device.','manacle'),contexts:[C('manacle.s2','历史叙事','The guards manacled the prisoner before moving him to the secure transport vehicle.','守卫给囚犯戴上手铐后，才把他押上安全运输车辆。','The guards manacled the prisoner / before moving him / to the secure / transport vehicle.','manacle.s2 作动词，表示用镣铐束缚手腕或行动自由。','守卫用手铐限制囚犯的行动。')],mistakes:[M('The guards manacled the prisoner by removing every restraint and giving him unrestricted freedom to leave.','The guards manacled the prisoner by fastening restraints around his wrists.','解除束缚与戴上镣铐相反。')],quiz:[Q('manacle',1,1,'A manacle is a?','shackle for the hands or feet','wooden mallet','shopping arcade','shackle for the hands or feet','manacle.s1 指镣铐。'),Q('manacle',2,2,'To manacle someone is to?','restrain them with a shackle','help them manage a business','feed them with milk','restrain them with a shackle','manacle.s2 作动词指给人戴上手铐。'),Q('manacle',3,1,'Which item could be a manacle?','a metal restraint around a wrist','a cloth curtain around a window','a wooden hammer used on a joint','a metal restraint around a wrist','手腕镣铐是 manacle。'),Q('manacle',4,1,'Manacle is most closely related to?','restraint','nourishment','malleability','restraint','manacle 用于束缚行动。')]});
D('manage',{etymology:E('Manage entered English through French from Italian maneggiare, “handle a horse,” from mano “hand”; it means direct work, succeed in doing something, or cope with limited resources.','manage'),contexts:[C('manage.s2','临时应变','Despite the power outage, the crew managed to finish the safety checks by using battery lamps.','尽管停电，工作人员还是设法用电池灯完成了安全检查。','Despite the power outage / the crew managed to finish the safety checks / by using / battery lamps.','manage.s2 指设法成功完成困难之事。','断电增加困难，但工作人员仍然完成检查。')],mistakes:[M('They managed to meet the deadline by abandoning the task and never submitting the required work.','They managed to meet the deadline by dividing the work and finishing the final review in time.','放弃任务并未成功完成截止事项。')],quiz:[Q('manage',1,1,'To manage a company is to?','direct or be in charge of it','make it temporarily from scrap','cause it to malfunction','direct or be in charge of it','manage.s1 指管理经营。'),Q('manage',2,2,'She managed to solve the problem means she?','succeeded in solving it','refused to attempt it','caused the problem deliberately','succeeded in solving it','manage.s2 指设法做到。'),Q('manage',3,3,'To manage with little money is to?','cope using what is available','spend without any limit','manacle the money','cope using what is available','manage.s3 指凑合应付困难情况。'),Q('manage',4,1,'Which sentence uses manage to mean “be in charge of”?','He manages a team of twelve engineers.','He managed to catch the bus.','She managed with only one flashlight.','He manages a team of twelve engineers.','manage a team 表示负责管理团队。')]});
D('manageable',{etymology:E('Manageable is formed from manage with -able; it describes something small or straightforward enough to handle successfully.','manageable'),contexts:[C('manageable.s1','工作规划','Breaking the report into weekly sections made the large assignment manageable.','把报告拆分成每周完成的部分后，这项大型作业就变得可处理了。','Breaking the report into weekly sections / made / the large assignment / manageable.','manageable 指规模或难度没有大到无法处理的。','分阶段使原本庞大的作业变得容易应对。')],mistakes:[M('The task was manageable even though no one could understand its requirements, access its materials, or complete any part of it.','The task became manageable after the team divided it into smaller, clear steps.','完全无法理解和完成的任务不是可处理的。')],quiz:[Q('manageable',1,1,'A manageable workload is?','not too difficult or large to handle','impossible for anyone to approach','already completed years ago','not too difficult or large to handle','manageable.s1 指可处理的。'),Q('manageable',2,1,'Which change makes a project more manageable?','dividing it into clear smaller steps','adding deadlines without resources','making every instruction unclear','dividing it into clear smaller steps','拆分任务有助于处理。'),Q('manageable',3,1,'Manageable is related to the verb?','manage','malign','maltreat','manage','manageable 由 manage 加 -able 构成。','word-formation'),Q('manageable',4,1,'A manageable problem can usually be?','handled successfully','ignored because it is imaginary','treated as a mammal','handled successfully','manageable 强调能够应对。')]});
D('management',{etymology:E('Management is formed from manage with -ment; it names the act of directing work or business and the people responsible for that direction.','management'),contexts:[C('management.s2','公司组织','Management announced that the company would consult staff before changing the shift schedule.','管理层宣布，在调整轮班表之前会征求员工意见。','Management announced / that the company would consult staff / before changing / the shift schedule.','management.s2 指负责指导公司或组织的管理人员群体。','管理层代表决策和管理团队发布安排。')],mistakes:[M('The company said management had announced the policy, although no managers or organizational leaders were involved.','The company said management announced the policy after the directors agreed on the change.','没有任何管理人员参与就不能把声明归于 management。')],quiz:[Q('management',1,1,'Management of a project is the act of?','directing and organizing its work','building a wooden mallet','treating a disease','directing and organizing its work','management.s1 指管理工作。'),Q('management',2,2,'In a company, management can mean?','the group of people who direct it','every customer who visits','only its manufactured goods','the group of people who direct it','management.s2 指管理层。'),Q('management',3,1,'Which phrase is natural?','senior management approved the plan','senior managements approved one plan','management to the plan did','senior management approved the plan','senior management 是常见搭配。','collocation'),Q('management',4,1,'Management is related to the verb?','manage','make','malt','manage','management 由 manage 加 -ment 构成。','word-formation')]});
D('manager',{etymology:E('Manager is formed from manage with -er; it names someone responsible for directing a business, team, or other operation.','manager'),contexts:[C('manager.s1','团队协作','The manager assigned each technician a section of the inspection and checked that safety procedures were followed.','经理把检查工作分配给每位技术员负责，并确认大家遵守安全规程。','The manager assigned each technician a section / of the inspection / and checked / that safety procedures were followed.','manager.s1 指负责管理企业、团队或工作的人员。','经理分配职责并监督团队工作。')],mistakes:[M('The manager was responsible for the team even though she neither directed its work nor had authority over its decisions.','The manager coordinated the team’s assignments and made sure the work was completed.','没有管理职责的人不符合 manager 的定义。')],quiz:[Q('manager',1,1,'A team manager usually?','coordinates and directs the team’s work','repairs every tool personally','records a ship’s longitude','coordinates and directs the team’s work','manager.s1 指团队或企业的管理者。'),Q('manager',2,1,'Which phrase is natural?','the manager of the store','the manager at to the store','the store managered yesterday','the manager of the store','可说 manager of a store。','collocation'),Q('manager',3,1,'A manager might do which task?','set priorities and assign staff','install every customer’s makeup','grow a mangrove forest','set priorities and assign staff','安排优先事项和员工职责属于管理工作。'),Q('manager',4,1,'Manager is the person noun related to?','manage','mandible','malice','manage','manager 由 manage 加 -er 构成。','word-formation')]});
D('managerial',{etymology:E('Managerial is formed from manager with -ial; it describes work, skills, or decisions connected with managing an organization or team.','managerial'),contexts:[C('managerial.s1','组织规划','The course develops managerial skills such as setting goals, delegating tasks, and giving feedback.','这门课程培养设定目标、分派任务和提供反馈等管理技能。','The course develops managerial skills / such as setting goals, delegating tasks, / and giving feedback.','managerial 指管理组织或团队相关的。','课程中的目标设定、任务分配和反馈都属于管理职能。')],mistakes:[M('The report called a routine laboratory measurement managerial even though it involved no supervision, planning, or organizational decisions.','The report described the director’s staffing and budget decisions as managerial duties.','普通测量并非组织管理职责。')],quiz:[Q('managerial',1,1,'Managerial decisions are connected with?','managing an organization','choosing cosmetics','classifying a mammal','managing an organization','managerial.s1 指管理方面的。'),Q('managerial',2,1,'Which is a managerial task?','assigning staff responsibilities','measuring a jaw bone','processing barley into malt','assigning staff responsibilities','分配员工职责是管理工作。'),Q('managerial',3,1,'Managerial is the adjective related to?','manager','mandarin','manacle','manager','managerial 由 manager 派生。','word-formation'),Q('managerial',4,1,'A managerial role commonly involves?','planning and directing work','only following instructions without authority','growing crops in tidal water','planning and directing work','管理岗位涉及计划和指导工作。')]});
D('mandarin',{etymology:E('Mandarin came through Portuguese from Malay menteri, “minister,” ultimately related to a Sanskrit term for counselor; it names standard Chinese, a historical Chinese official, or a small citrus fruit.','mandarin'),contexts:[C('mandarin.s1','语言教育','The course teaches Mandarin pronunciation alongside characters used in contemporary written Chinese.','这门课程在教授现代书面汉语常用汉字的同时，也教授普通话发音。','The course teaches Mandarin pronunciation / alongside characters / used in contemporary written Chinese.','mandarin.s1 指标准汉语、普通话。','课程涉及普通话语音和现代书面汉语。')],mistakes:[M('The student said she was studying Mandarin when she meant a variety of orange and was not studying a language.','The student said she was studying Mandarin when she meant standard Chinese speech.','水果义与语言义要依据上下文区分。')],quiz:[Q('mandarin',1,1,'In a language class, Mandarin means?','standard Chinese','a small orange','a wooden hammer','standard Chinese','mandarin.s1 指普通话。'),Q('mandarin',2,2,'Historically, a mandarin could be?','a Chinese official','a mammal','a computer virus','a Chinese official','mandarin.s2 指旧时中国官吏。'),Q('mandarin',3,3,'A mandarin at a fruit stand is?','a small sweet orange','a government order','a type of metal','a small sweet orange','mandarin.s3 指蜜柑。'),Q('mandarin',4,1,'Which context makes the language sense clear?','She practiced Mandarin tones with her tutor.','He peeled a mandarin after lunch.','The historian wrote about an imperial mandarin.','She practiced Mandarin tones with her tutor.','tone practice 明确指语言义。')]});
D('mandate',{etymology:E('Mandate comes from Latin mandatum, “command,” from mandare “to entrust or order”; it can mean elected authority, an official command, or formally require or authorize an action.','mandate'),contexts:[C('mandate.s3','公共政策','The new safety law mandates annual inspections of elevators in public buildings.','新安全法规定公共建筑的电梯必须每年接受检查。','The new safety law mandates / annual inspections / of elevators / in public buildings.','mandate.s3 作动词，表示正式命令、授权或强制要求。','法律将年度检查规定为必须履行的要求。')],mistakes:[M('The law mandates annual inspections by explicitly making them optional and forbidding officials from requiring them.','The law mandates annual inspections by requiring building owners to arrange them each year.','将检查规定为可选与强制要求相反。')],quiz:[Q('mandate',1,1,'An electoral mandate is?','authority given to a government by voters','a shopping center','a jaw bone','authority given to a government by voters','mandate.s1 指选举赋予的授权。'),Q('mandate',2,2,'An official mandate may be?','a formal order','a citrus fruit','a temporary cosmetic','a formal order','mandate.s2 可指正式命令。'),Q('mandate',3,3,'To mandate a safety check is to?','require it officially','suggest it without obligation','cancel it permanently','require it officially','mandate.s3 指正式要求。'),Q('mandate',4,1,'A government claims a mandate when it says it has?','publicly granted authority to act','no legal or electoral support','a medical condition','publicly granted authority to act','民众通过选举授予政府行使职权的授权。')]});
D('mandatory',{etymology:E('Mandatory comes from Latin mandatorius, from mandare “to command”; it means required by law, rule, or an official instruction.','mandatory'),contexts:[C('mandatory.s1','校园规定','Safety glasses are mandatory in the chemistry laboratory whenever students handle reagents.','学生在化学实验室处理试剂时必须佩戴护目镜。','Safety glasses are mandatory / in the chemistry laboratory / whenever students / handle reagents.','mandatory 指法律或规则规定必须执行的。','实验室规定要求处理试剂时佩戴护目镜。')],mistakes:[M('The notice called the safety glasses mandatory but said students could freely choose not to wear them.','The notice made safety glasses mandatory whenever reagents were handled.','允许随意不戴与 mandatory 的强制性相矛盾。')],quiz:[Q('mandatory',1,1,'A mandatory rule is?','required','optional','unrelated to any instruction','required','mandatory.s1 指强制的、必需的。'),Q('mandatory',2,1,'If attendance is mandatory, students?','must attend','may ignore the class without consequence','are prohibited from entering','must attend','mandatory 表示必须参加。'),Q('mandatory',3,1,'Which phrase is natural?','mandatory safety training','mandatory maybe training if desired','mandatory of to train','mandatory safety training','mandatory 可修饰 training。','collocation'),Q('mandatory',4,1,'Mandatory contrasts with?','optional','official','required','optional','optional 是可选的，与 mandatory 相反。','confusable')]});
D('mandible',{etymology:E('Mandible comes from Latin mandibula, “jaw,” from mandere “to chew”; it names the lower jawbone or a jaw-like part in an insect or bird.','mandible'),contexts:[C('mandible.s1','动物解剖','The fossil’s lower mandible was preserved, allowing researchers to compare its jaw shape with related species.','这块化石的下颌保存了下来，使研究人员能够将其颌骨形状与近缘物种进行比较。','The fossil’s lower mandible was preserved / allowing researchers / to compare its jaw shape / with related species.','mandible.s1 指下颌骨，也可指昆虫或鸟类类似颚部的结构。','保存的下颌骨可用于形态比较。')],mistakes:[M('The anatomist identified the upper skull roof as the mandible even though it was not part of the lower jaw.','The anatomist identified the lower jawbone as the mandible.','mandible 指下颌，不是头骨顶部。')],quiz:[Q('mandible',1,1,'The human mandible is the?','lower jawbone','upper arm bone','breast gland','lower jawbone','mandible.s1 指下颌。'),Q('mandible',2,1,'An insect’s mandibles are used mainly for?','biting or chewing','hearing distant sounds','producing milk','biting or chewing','昆虫的颚用于咬合或咀嚼。'),Q('mandible',3,1,'Which phrase uses mandible correctly?','a fracture of the lower mandible','a malady in the shopping mall','a mandible of barley malt','a fracture of the lower mandible','下颌骨骨折可称 mandible fracture。','collocation'),Q('mandible',4,1,'Mandible is most closely related to?','jaw','mane','manganese','jaw','mandible 的意思是颌骨。','meaning')]});
D('mane',{etymology:E('Mane comes from Old English manu and related Germanic words; it is the long hair growing along the neck of a horse or lion.','mane'),contexts:[C('mane.s1','野生动物观察','The lion shook rainwater from its mane and settled beneath the ledge.','狮子抖掉鬃毛上的雨水，随后卧在岩架下。','The lion shook rainwater / from its mane / and settled / beneath the ledge.','mane 指马或狮子颈部长长的鬃毛。','狮子甩动颈部毛发上的雨水。')],mistakes:[M('The horse’s mane referred to its short hoof hair rather than the long hair growing along its neck.','The horse’s mane was the long hair flowing along its neck.','蹄部不是 mane 的生长部位。')],quiz:[Q('mane',1,1,'A lion’s mane is its?','long hair around its neck','lower jawbone','wooden tool','long hair around its neck','mane.s1 指颈部鬃毛。'),Q('mane',2,1,'Which animal typically has a mane?','a horse','a trout','a butterfly','a horse','马有鬃毛。'),Q('mane',3,1,'The word mane is about an animal’s?','hair','milk gland','jawbone','hair','mane 指动物毛发。'),Q('mane',4,1,'A groom might brush a horse’s?','mane','malady','manganese','mane','马鬃需要梳理。')]});
D('maneuver',{etymology:E('Maneuver comes from French manœuvre, from Latin manu operari “work by hand”; it names a careful movement or strategy and the act of skillfully moving or directing something.','maneuver'),contexts:[C('maneuver.s3','驾驶训练','The driver maneuvered the van slowly into the narrow loading bay without touching either wall.','司机缓慢地把厢式货车驶入狭窄装卸区，没有碰到两侧墙壁。','The driver maneuvered the van slowly / into the narrow loading bay / without touching / either wall.','maneuver.s3 作动词，指在狭小空间内小心熟练地移动或转向。','驾驶员精准调整方向驶入窄小空间。')],mistakes:[M('She maneuvered the van into the bay by driving straight into a wall and leaving it stuck.','She maneuvered the van into the bay by making a series of careful turns.','撞墙卡住不是熟练操控车辆。')],quiz:[Q('maneuver',1,1,'A careful maneuver by a driver is?','a movement requiring skill and attention','a type of citrus fruit','a medical diagnosis','a movement requiring skill and attention','maneuver.s1 指需要谨慎的机动动作。'),Q('maneuver',2,2,'A political maneuver may be?','a clever strategy to gain an advantage','a lower jawbone','a mandatory annual check','a clever strategy to gain an advantage','maneuver.s2 可指策略或花招。'),Q('maneuver',3,3,'To maneuver a car into a tight space is to?','move or turn it carefully','leave it running unattended','change its paint color','move or turn it carefully','maneuver.s3 指小心操纵车辆。'),Q('maneuver',4,4,'To maneuver people into supporting a plan is to?','direct them strategically, sometimes unfairly','care for them medically','identify their jawbones','direct them strategically, sometimes unfairly','maneuver.s4 指用策略调动或操纵人。')]});
D('manful',{etymology:E('Manful is formed from man with -ful; it traditionally describes courage and resolution, though it is now often considered old-fashioned or gendered.','manful'),contexts:[C('manful.s1','历史叙事','The chronicler praised the crew’s manful effort to keep the rescue boat afloat through the storm.','编年史作者赞扬船员们在风暴中竭力使救援船保持漂浮的坚定勇气。','The chronicler praised / the crew’s manful effort / to keep the rescue boat afloat / through the storm.','manful 指勇敢而坚定的，现今常带有旧式或性别化语感。','船员在风暴中坚持救援，表现出勇气和决心。')],mistakes:[M('The account called the crew’s retreat from danger manful even though they abandoned the rescue and made no effort to help.','The account described their determined effort to continue the rescue as manful.','毫无努力地放弃救援与勇敢坚定不符。')],quiz:[Q('manful',1,1,'A manful effort shows?','courage and determination','a desire to cause harm','a lack of any effort','courage and determination','manful.s1 指勇敢坚定的。'),Q('manful',2,1,'Which action might an old-fashioned writer call manful?','persisting bravely through a difficult rescue','avoiding every challenge and quitting at once','complaining about a shopping center','persisting bravely through a difficult rescue','在困难救援中坚持体现勇气。'),Q('manful',3,1,'Manful is often considered?','old-fashioned or gendered','a technical term for a mammal','the standard name for a shopping mall','old-fashioned or gendered','该词现今常被视为旧式或带性别色彩。','register'),Q('manful',4,1,'Manful is closest here to?','courageous','malicious','manageable','courageous','courageous 表示勇敢。','meaning')]});
D('manganese',{etymology:E('Manganese takes its name through French from Italian manganese, associated with the mineral magnesia; it is a brittle metallic element used in steel and needed in small amounts by living things.','manganese'),contexts:[C('manganese.s1','冶金材料','The steel contained manganese, which improved its strength and helped it resist wear.','这种钢材含有锰，这提高了它的强度并帮助它抵抗磨损。','The steel contained manganese / which improved its strength / and helped it / resist wear.','manganese 是一种金属元素，常用于钢材，也为生物所需的微量元素。','锰被加入钢中以改善材料性能。')],mistakes:[M('The chemist identified manganese as a soft liquid gas that could not be added to metal alloys.','The chemist identified manganese as a brittle metallic element used in some steel alloys.','manganese 是金属元素，不是液态气体。')],quiz:[Q('manganese',1,1,'Manganese is a?','metallic chemical element','shopping center','type of wooden hammer','metallic chemical element','manganese.s1 指化学元素锰。'),Q('manganese',2,1,'Manganese may be added to?','steel','makeup powder only','malaria medicine as a parasite','steel','锰用于某些钢材。'),Q('manganese',3,1,'Which symbol represents manganese?','Mn','Mg','Ma','Mn','锰的化学符号为 Mn。'),Q('manganese',4,1,'Manganese is required by living things in?','small amounts','unlimited quantities','no biological context ever','small amounts','生物需要少量锰。')]});
D('mangle',{etymology:E('Mangle came through Dutch from a Latin word for a machine; as a verb it means badly damage or distort, and as a noun it names rollers used to squeeze water from clothes.','mangle'),contexts:[C('mangle.s2','口译复核','The summary mangled the witness’s words so badly that it made her careful warning sound like an accusation.','摘要把证人的话歪曲得很严重，使她谨慎的警告听起来像指控。','The summary mangled the witness’s words / so badly / that it made her careful warning / sound like an accusation.','mangle.s2 作动词，指错误转述或曲解话语，使意思变样。','错误转述把警告变成了指控。')],mistakes:[M('The editor said the quote was mangled even though it preserved every word and the speaker’s meaning exactly.','The editor said the quote was mangled because it replaced the speaker’s caution with a claim she never made.','准确保留原意与曲解相反。')],quiz:[Q('mangle',1,1,'To mangle a metal part is to?','damage it badly','polish it perfectly','manage a team','damage it badly','mangle.s1 指严重损毁。'),Q('mangle',2,2,'To mangle someone’s words is to?','repeat or quote them in a distorted way','record them exactly','translate them flawlessly','repeat or quote them in a distorted way','mangle.s2 指曲解话语。'),Q('mangle',3,3,'A laundry mangle uses rollers to?','squeeze water from clothes','shape a mammal’s jaw','measure longitude','squeeze water from clothes','mangle.s3 指轧布或拧干机。'),Q('mangle',4,1,'Which sentence uses mangle to mean distort?','The report mangled her careful statement.','The report quoted her statement exactly.','The mangle dried the sheets between rollers.','The report mangled her careful statement.','该句表示歪曲了她的话。')]});
D('mangrove',{etymology:E('Mangrove was borrowed from Spanish manglar with the English element grove; it names salt-tolerant trees and shrubs that form forests in tropical tidal wetlands.','mangrove'),contexts:[C('mangrove.s1','海岸生态','Mangrove roots trapped sediment along the tidal creek and provided shelter for young fish.','红树林的根系在潮汐溪流边拦截沉积物，并为幼鱼提供庇护。','Mangrove roots trapped sediment / along the tidal creek / and provided shelter / for young fish.','mangrove 指生长在潮汐沼泽中的耐盐树木或灌木。','红树林生长于潮间带，根系可拦截沉积物并提供栖息地。')],mistakes:[M('The guide described the mangrove as a freshwater alpine flower that grows only on dry mountain peaks.','The guide described mangroves as salt-tolerant trees growing in tropical tidal wetlands.','红树林耐盐并生长于潮汐湿地，不是高山旱地花卉。')],quiz:[Q('mangrove',1,1,'A mangrove is a salt-tolerant?','tree or shrub','metal alloy','citrus fruit','tree or shrub','mangrove.s1 指红树林植物。'),Q('mangrove',2,1,'Mangroves commonly grow in?','tropical tidal wetlands','dry polar mountains','indoor shopping centers','tropical tidal wetlands','红树林适应热带潮间湿地。'),Q('mangrove',3,1,'Mangrove roots can help?','stabilize sediment and shelter young fish','produce a lower jawbone','cause a computer malfunction','stabilize sediment and shelter young fish','红树林根系可稳定沉积物并提供栖息地。'),Q('mangrove',4,1,'A mangrove forest is part of a?','coastal ecosystem','metal factory','political mandate','coastal ecosystem','红树林是海岸生态系统的一部分。')]});
D('mania',{etymology:E('Mania comes from Greek mania, “madness”; it can mean an extremely strong enthusiasm or a serious mental state involving abnormal excitement.','mania'),contexts:[C('mania.s1','社会潮流','The sudden mania for limited-edition sneakers drove resale prices far above their original cost.','对限量版运动鞋突然出现的狂热，使转售价远高于原价。','The sudden mania for limited-edition sneakers / drove resale prices / far above / their original cost.','mania 可指对某事物极强烈的热情或狂热。','抢购热潮推高了转售价格。')],mistakes:[M('The brief interest in the shoes was called a mania even though almost nobody cared about them or sought to buy them.','The widespread intense demand for the shoes was described as a mania.','几乎无人关注不构成狂热。')],quiz:[Q('mania',1,1,'A mania for a product is?','an extremely strong enthusiasm for it','a mild passing curiosity','a professional manager','an extremely strong enthusiasm for it','mania.s1 指狂热。'),Q('mania',2,1,'Which trend could be called a mania?','huge crowds competing to buy one collectible toy','one person casually noticing a toy','a company recalling a faulty product','huge crowds competing to buy one collectible toy','大批人热烈追捧某物可称 mania。'),Q('mania',3,1,'Mania can also name?','a serious mental state involving abnormal excitement','a kind of mangrove','a formal order','a serious mental state involving abnormal excitement','mania 也可指躁狂状态。'),Q('mania',4,1,'Mania is stronger than?','interest','obsession-like enthusiasm','frenzy','interest','mania 表示比一般兴趣强得多的狂热。','meaning')]});
D('maniac',{etymology:E('Maniac derives from mania with -ac; as a noun it names someone acting violently or with extreme obsession, and as an adjective it means wildly frenzied.','maniac'),contexts:[C('maniac.s2','行为描写','The driver made a maniac turn through the crowded lot, forcing pedestrians to jump back.','司机在拥挤的停车场里疯狂转弯，逼得行人纷纷后退。','The driver made / a maniac turn / through the crowded lot / forcing pedestrians to jump back.','maniac.s2 作形容词，表示疯狂、失控的。','车辆动作危险而狂乱，不是正常谨慎驾驶。')],mistakes:[M('The driver’s slow, cautious turn through an empty lot was called maniac even though it posed no danger or disorder.','The driver made a maniac turn through a crowded lot at dangerous speed.','谨慎缓慢的动作不符合疯狂失控之意。')],quiz:[Q('maniac',1,1,'A maniac as a noun may be?','someone acting violently or extremely obsessively','a person who directs a company','a mammalian gland','someone acting violently or extremely obsessively','maniac.s1 指行为暴烈或痴迷过度的人。'),Q('maniac',2,2,'A maniac driver might drive?','wildly and dangerously','slowly and carefully at all times','only on a farm road','wildly and dangerously','maniac.s2 作形容词指疯狂的。'),Q('maniac',3,1,'Which behavior sounds maniac?','racing through a crowded street without regard for others','stopping at a red light','checking mirrors before turning','racing through a crowded street without regard for others','无视他人危险疾驰显得疯狂。'),Q('maniac',4,1,'Maniac is related to the noun?','mania','mane','mandible','mania','maniac 由 mania 派生。','word-formation')]});
D('manifest',{etymology:E('Manifest comes from Latin manifestus, “plainly seen”; as an adjective it means obvious, as a verb to show clearly, and as a noun a cargo or passenger list.','manifest'),contexts:[C('manifest.s2','健康观察','The allergy manifested itself as a rash several hours after the patient ate the nuts.','患者吃下坚果几小时后，过敏反应以皮疹的形式显现出来。','The allergy manifested itself / as a rash / several hours / after the patient ate the nuts.','manifest.s2 作动词，表示清楚地显示或显露某种特征、感受或病情。','皮疹是过敏反应显露出的症状。')],mistakes:[M('The allergy manifested itself by producing no sign or symptom that anyone could observe.','The allergy manifested itself as swelling and a rash.','没有任何可见表现就没有显露出来。')],quiz:[Q('manifest',1,1,'A manifest fact is?','clear and easy to notice','hidden from every observer','a type of citrus fruit','clear and easy to notice','manifest.s1 作形容词指明显的。'),Q('manifest',2,2,'To manifest a feeling is to?','show it clearly','conceal it completely','make a cargo list only','show it clearly','manifest.s2 作动词表示显露。'),Q('manifest',3,3,'A ship’s manifest lists?','goods or passengers','a list of illnesses only','mangrove roots','goods or passengers','manifest.s3 指货物或旅客舱单。'),Q('manifest',4,2,'A symptom may manifest itself by?','appearing clearly','being permanently absent','changing into a shopping mall','appearing clearly','症状显现即 manifest itself。')]});
D('manifestation',{etymology:E('Manifestation is formed from manifest with -ation; it names a visible sign or expression of a quality, a visible appearance of a spirit, or a public protest gathering.','manifestation'),contexts:[C('manifestation.s1','情绪观察','Her patience was a manifestation of years of practice listening calmly to difficult complaints.','她的耐心体现了多年练习冷静倾听棘手抱怨的结果。','Her patience was / a manifestation / of years of practice / listening calmly to difficult complaints.','manifestation.s1 指显示某种性质或感受存在的表现。','耐心是长期训练形成的可见表现。')],mistakes:[M('The smile was called a manifestation of anger even though it showed no hostility and the person felt calm.','The clenched jaw and threatening words were manifestations of anger.','没有敌意且平静的表情不能说明愤怒显现。')],quiz:[Q('manifestation',1,1,'A manifestation of courage is?','a visible sign or expression of courage','a secret thought with no expression','a shopping mall','a visible sign or expression of courage','manifestation.s1 指某种特质的表现。'),Q('manifestation',2,2,'A spiritual manifestation is?','an appearance of a spirit in visible form','a cargo list','a medical manager','an appearance of a spirit in visible form','manifestation.s2 可指神灵显现。'),Q('manifestation',3,3,'A public manifestation may be?','a large protest gathering','a private office meeting of two people','a quiet note sent by email','a large protest gathering','manifestation.s3 指示威集会。'),Q('manifestation',4,1,'A rash can be a manifestation of?','an allergic reaction','a political mandate','a wooden mallet','an allergic reaction','皮疹是过敏反应的可见表现。')]});
D('manifesto',{etymology:E('Manifesto comes from Italian manifesto, “public declaration,” from Latin manifestus “clear”; it is a written statement of a political party’s aims or principles.','manifesto'),contexts:[C('manifesto.s1','政治传播','The party published a manifesto outlining its proposals for housing, transport, and public health.','该党发表宣言，概述其在住房、交通和公共卫生方面的提议。','The party published a manifesto / outlining its proposals / for housing, transport, / and public health.','manifesto 指政治团体公开阐述目标或原则的书面文件。','文件列出政党的政策主张。')],mistakes:[M('The campaign called a blank sheet with no aims or proposals its manifesto.','The campaign’s manifesto set out the party’s aims and policy proposals.','没有目标或原则的空白文件不是宣言。')],quiz:[Q('manifesto',1,1,'A political manifesto sets out a party’s?','aims and principles','members’ lunch orders','medical diagnoses','aims and principles','manifesto.s1 指政党宣言或政纲。'),Q('manifesto',2,1,'A party may publish a manifesto before?','an election','a mallet is made','a mammal is born','an election','政党常在选举前公布政纲。'),Q('manifesto',3,1,'Which document is a manifesto?','a written statement of a movement’s goals','an unlabeled shopping receipt','a list of passengers on a ship','a written statement of a movement’s goals','公开说明运动目标的文件符合 manifesto。'),Q('manifesto',4,1,'A manifesto is usually?','written and publicly declared','a type of machine','an accidental illness','written and publicly declared','manifesto 通常是公开发表的书面宣言。')]});
D('manifold',{etymology:E('Manifold combines Old English manig “many” and feald “fold”; it can mean many-sided, a duplicate copy or branching pipe, and the act of making copies or increasing variety.','manifold'),contexts:[C('manifold.s1','复杂影响','The new transit line had manifold effects: it shortened commutes, changed rents, and brought more visitors downtown.','新交通线路产生了多方面影响：缩短通勤时间、改变租金，并为市中心带来更多访客。','The new transit line had manifold effects / it shortened commutes, / changed rents, / and brought more visitors downtown.','manifold.s1 形容由许多不同部分或方面组成的、多种多样的。','句中列出多个不同影响。')],mistakes:[M('The proposal had a single narrow consequence, yet the report called its effects manifold.','The proposal had manifold effects across transport, housing, and local business.','只有一个单一影响不能称为多方面的。')],quiz:[Q('manifold',1,1,'Manifold effects are?','many and varied','only one and identical','impossible to observe','many and varied','manifold.s1 指多方面的。'),Q('manifold',2,2,'A manifold may be?','a branched pipe or a duplicate document','a lower jawbone only','a political party’s aims','a branched pipe or a duplicate document','manifold.s2 可指歧管或复写本。'),Q('manifold',3,3,'To manifold copies of a form is to?','make multiple copies','damage it badly','force someone into a shackle','make multiple copies','manifold.s3 作动词可表示复印。'),Q('manifold',4,1,'A manifold set of reasons includes?','several different reasons','one reason repeated exactly','no reasons at all','several different reasons','manifold 强调多种不同方面。')]});
D('manipulate',{etymology:E('Manipulate comes from Latin manipulus, “handful,” from manus “hand”; it means handle skillfully, unfairly control a person, or alter data to create a false result.','manipulate'),contexts:[C('manipulate.s3','数据审计','The analyst manipulated the figures by excluding months with losses, making the investment appear profitable.','分析师通过删去亏损月份篡改数据，使这项投资看起来有利可图。','The analyst manipulated the figures / by excluding months with losses / making the investment / appear profitable.','manipulate.s3 指不诚实地更改数字或信息以制造虚假结果。','删去不利月份扭曲了真实表现。')],mistakes:[M('The analyst manipulated the data accurately by retaining every month and reporting the full results without alteration.','The analyst manipulated the data by selectively changing figures to mislead readers.','忠实完整地报告数据不属于篡改。')],quiz:[Q('manipulate',1,1,'To manipulate a delicate instrument is to?','handle or control it skillfully','leave it untouched forever','write a political manifesto','handle or control it skillfully','manipulate.s1 指熟练操作。'),Q('manipulate',2,2,'To manipulate a person unfairly is to?','control them for one’s own advantage','give them full independent choice','measure their jawbone','control them for one’s own advantage','manipulate.s2 指不公平地操纵他人。'),Q('manipulate',3,3,'To manipulate figures dishonestly is to?','alter information to create a false impression','publish every number accurately','ask someone to check a calculation','alter information to create a false impression','manipulate.s3 指篡改数据。'),Q('manipulate',4,1,'A surgeon may manipulate tissue by?','carefully handling it during an operation','falsifying the patient’s records','making a public protest','carefully handling it during an operation','医学操作中可指熟练处理组织。')]});
D('manipulation',{etymology:E('Manipulation is formed from manipulate with -ion; it names skillful handling, unfair control of people or events, or dishonest alteration of data or markets.','manipulation'),contexts:[C('manipulation.s2','人际关系','The counselor helped him recognize emotional manipulation that made him feel guilty whenever he set a boundary.','咨询师帮助他识别情感操纵：每当他设定界限时，对方就让他感到内疚。','The counselor helped him recognize / emotional manipulation / that made him feel guilty / whenever he set a boundary.','manipulation.s2 指为自身利益而不公平地控制他人或局势。','通过制造内疚感迫使对方放弃界限属于操纵。')],mistakes:[M('The counselor called the conversation manipulation even though both people spoke openly, respected boundaries, and made choices freely.','The counselor identified manipulation when one person used guilt to pressure the other into surrendering a boundary.','自愿交流并尊重界限不构成不公平控制。')],quiz:[Q('manipulation',1,1,'Manipulation of a tool may mean?','skillful handling or control','a public protest','a serious disease','skillful handling or control','manipulation.s1 指操作处理。'),Q('manipulation',2,2,'Emotional manipulation is?','unfairly influencing someone for one’s advantage','offering honest information without pressure','a copy made with a manifold','unfairly influencing someone for one’s advantage','manipulation.s2 指操纵摆布。'),Q('manipulation',3,3,'Market manipulation may involve?','dishonestly controlling prices or information','accurately reporting every trade','growing salt-tolerant trees','dishonestly controlling prices or information','manipulation.s3 指市场操纵。'),Q('manipulation',4,1,'Manipulation is the noun related to?','manipulate','malady','mandarin','manipulate','manipulation 由 manipulate 派生。','word-formation')]});
D('manipulative',{etymology:E('Manipulative is formed from manipulate with -ive; it describes unfairly influencing people for one’s advantage or involving skilled physical handling.','manipulative'),contexts:[C('manipulative.s1','团队沟通','The manager’s manipulative praise was followed by a request that employees work unpaid overtime.','经理先用操纵性的赞扬，随后要求员工无偿加班。','The manager’s manipulative praise / was followed by a request / that employees work / unpaid overtime.','manipulative.s1 指善于以不可信任的方式影响他人以谋取自身利益的。','赞扬被用作施压手段，促使员工接受无偿加班。')],mistakes:[M('The manager was manipulative because she gave employees clear information and let them freely decline the request.','The manager was manipulative because she used flattery and guilt to pressure employees into unpaid work.','尊重员工选择且透明沟通不构成操纵。')],quiz:[Q('manipulative',1,1,'A manipulative person tries to?','influence others unfairly for personal advantage','make every choice freely informed','grow plants in rich soil','influence others unfairly for personal advantage','manipulative.s1 指操纵他人。'),Q('manipulative',2,2,'A manipulative technique may involve?','skilled physical handling or technical control','a public vote only','a serious lack of food','skilled physical handling or technical control','manipulative.s2 可指手法操作的。'),Q('manipulative',3,1,'Which behavior seems manipulative?','using guilt to make a friend lend money','accepting a friend’s refusal without pressure','explaining a request honestly','using guilt to make a friend lend money','利用内疚施压体现操纵。'),Q('manipulative',4,1,'Manipulative is related to the verb?','manipulate','manufacture','manacle','manipulate','manipulative 由 manipulate 派生。','word-formation')]});
D('mankind',{etymology:E('Mankind combines man in the older general sense “human being” with kind; it refers to humanity collectively, though the term can sound dated or gender-exclusive today.','mankind'),contexts:[C('mankind.s1','历史文本','The old inscription speaks of mankind as one community responsible for protecting the planet.','这段古老铭文把人类称为一个共同体，认为其有责任保护地球。','The old inscription speaks of mankind / as one community / responsible / for protecting the planet.','mankind.s1 是较旧的泛称，指全体人类。','句子把所有人看作共同承担责任的人类整体。')],mistakes:[M('The text used mankind to mean only one individual man, excluding all other people.','The older text used mankind broadly to refer to humanity as a whole.','该词在这一用法中泛指人类整体。')],quiz:[Q('mankind',1,1,'In an older general usage, mankind means?','humanity as a whole','only one adult male','a group of managers','humanity as a whole','mankind.s1 泛指人类。'),Q('mankind',2,2,'Mankind can also contrast human beings with?','nature or animals','a shopping mall','a wooden mallet','nature or animals','mankind.s2 可指人类，与自然或动物相对。'),Q('mankind',3,1,'Which modern wording is often more gender-inclusive than mankind?','humanity','manful','malevolence','humanity','humanity 更明确地涵盖所有人。','register'),Q('mankind',4,1,'A history of mankind studies?','human beings collectively','one company’s manufacturers','only male managers','human beings collectively','mankind 通常指全人类。')]});
D('manly',{etymology:E('Manly is formed from man with -ly; it describes qualities traditionally associated with men, though that gendered ideal can vary by culture and era.','manly'),contexts:[C('manly.s1','文学评论','The novel praises the hero’s manly courage, reflecting the era’s traditional ideal of masculine conduct.','小说赞扬主人公具有男子气概的勇气，体现了那个时代对男性行为的传统理想。','The novel praises / the hero’s manly courage / reflecting / the era’s traditional ideal of masculine conduct.','manly 指被传统观念认为具有男子气概的品质。','语境将勇气与特定时代的男性气质观念联系起来。')],mistakes:[M('The critic called a patient and gentle act manly because it fit every culture’s single fixed definition of masculinity.','The critic called the hero’s courage manly according to the novel’s traditional gender ideals.','该词涉及传统性别观念，不存在跨文化唯一标准。')],quiz:[Q('manly',1,1,'Manly traditionally describes qualities thought typical of?','a man','a shopping center','a medical condition','a man','manly.s1 指传统观念中的男子气概。'),Q('manly',2,1,'A writer might describe courage as manly to reflect?','a particular cultural ideal of masculinity','a chemical property','a legal order','a particular cultural ideal of masculinity','manly 的评价受时代文化观念影响。'),Q('manly',3,1,'Which is closest to manly in the source sense?','masculine','mammalian','manageable','masculine','masculine 与 manly 意义相关。','meaning'),Q('manly',4,1,'Manly is the adjective related to?','man','mane','manner','man','manly 由 man 加 -ly 构成。','word-formation')]});
D('manned',{etymology:E('Manned is the past participle of man used adjectivally; it describes a vehicle or post with a human crew or operator on duty.','manned'),contexts:[C('manned.s1','航天任务','The capsule was designed for a manned mission, with room for two astronauts and their life-support equipment.','这艘太空舱为载人任务设计，可容纳两名宇航员及其生命保障设备。','The capsule was designed / for a manned mission / with room / for two astronauts and their life-support equipment.','manned 指有人员乘坐或值守的。','太空舱内安排了宇航员和生命保障设备。')],mistakes:[M('The observatory was manned all night even though it was fully automated and no operator was on duty.','The observatory was manned all night by an astronomer monitoring the instruments.','没有值守人员的自动设备不属于有人值守。')],quiz:[Q('manned',1,1,'A manned spacecraft carries?','a human crew','only automatic sensors','cargo with no operator','a human crew','manned.s1 指载人的。'),Q('manned',2,1,'A manned station has?','people on duty','no staff or operators','only a mannequin','people on duty','manned 也可指有人值守。'),Q('manned',3,1,'Which is a manned mission?','a flight carrying astronauts','an uncrewed probe controlled automatically','a shipment of fertilizer only','a flight carrying astronauts','载有宇航员的飞行是载人任务。'),Q('manned',4,1,'Manned is related to the verb?','man, meaning staff or operate','mane, meaning grow hair','mangle, meaning damage','man, meaning staff or operate','动词 man 可表示配备人员值守。','word-formation')]});
D('mannequin',{etymology:E('Mannequin came through French from Dutch manneken, “little man”; it names a human-shaped model used to display clothing.','mannequin'),contexts:[C('mannequin.s1','服装展示','The tailor pinned the coat on a mannequin to check how its shoulders and sleeves would hang.','裁缝把外套别在人体模型上，检查肩部和袖子的垂坠效果。','The tailor pinned the coat / on a mannequin / to check / how its shoulders and sleeves would hang.','mannequin 指用于展示衣服的人体模型。','裁缝通过模型检查服装版型。')],mistakes:[M('The shop displayed a mannequin that was a living customer wearing the coat for a private fitting.','The shop displayed the coat on a mannequin, a human-shaped model.','mannequin 是展示用模型，不是顾客本人。')],quiz:[Q('mannequin',1,1,'A mannequin is used to?','display clothing on a human-shaped model','measure longitude','grow mangrove roots','display clothing on a human-shaped model','mannequin.s1 指人体服装模型。'),Q('mannequin',2,1,'A store might put a jacket on a?','mannequin','mandible','manacle','mannequin','商店会把衣服穿在人体模型上展示。'),Q('mannequin',3,1,'A mannequin is not usually?','a living customer','a human-shaped model','a display form','a living customer','mannequin 通常是模型，不是真人。'),Q('mannequin',4,1,'Which shop fixture is a mannequin?','a full-size figure wearing a dress','a shelf holding folded shirts','a till that rings up sales','a full-size figure wearing a dress','穿着衣服的人体模型是 mannequin。')]});
D('manner',{etymology:E('Manner comes from Old French maniere, “way or fashion”; it can mean how something is done, a person’s behavior, social politeness, or a kind in “all manner of.”','manner'),contexts:[C('manner.s2','日常交流','Her calm manner helped the nervous visitor explain what had happened.','她平和的举止帮助紧张的访客讲清楚了事情经过。','Her calm manner / helped the nervous visitor / explain / what had happened.','manner.s2 指一个人待人接物的行为方式或态度。','平和的表现让对方更容易沟通。')],mistakes:[M('He spoke in a hostile manner while smiling warmly, listening carefully, and treating everyone with respect.','He spoke in a hostile manner by interrupting others and using contemptuous language.','尊重倾听的行为与敌对态度不相符。')],quiz:[Q('manner',1,1,'The manner in which a task is done is its?','way or method','shopping district','medical illness','way or method','manner.s1 指方式、方法。'),Q('manner',2,2,'A person’s manner is their?','way of behaving toward others','jawbone','fertilizer','way of behaving toward others','manner.s2 指举止态度。'),Q('manner',3,3,'Good manners are?','polite social behavior','a way to copy a document','a type of tree','polite social behavior','manner.s3 指礼仪、礼貌。'),Q('manner',4,4,'“All manner of books” means?','many kinds of books','one book only','books written by managers only','many kinds of books','manner.s4 可指种类。')]});
D('mannerism',{etymology:E('Mannerism is formed from manner with -ism; it can mean an individual’s repeated small habit or behavior that seems artificial and insincere.','mannerism'),contexts:[C('mannerism.s1','演讲观察','The speaker had a mannerism of tapping the lectern twice before answering a difficult question.','这位演讲者有个小习惯：回答难题前会敲两下讲台。','The speaker had a mannerism / of tapping the lectern twice / before answering / a difficult question.','mannerism.s1 指个人反复出现的小动作或说话习惯。','敲讲台是一个固定重复的小动作。')],mistakes:[M('Her single unplanned stumble was called a mannerism even though she never repeated it and did not habitually move that way.','Her repeated habit of tapping the lectern before speaking was a mannerism.','偶发的一次动作不是习惯性举止。')],quiz:[Q('mannerism',1,1,'A mannerism is often?','a small repeated personal habit','a legal requirement','a mammal’s jawbone','a small repeated personal habit','mannerism.s1 指习惯性小动作。'),Q('mannerism',2,2,'An actor’s artificial mannerism may seem?','insincere or affected','spontaneous and natural','a kind of fertilizer','insincere or affected','mannerism.s2 指矫揉造作。'),Q('mannerism',3,1,'Which could be a mannerism?','twirling a pen before every answer','sneezing once because of dust','changing a one-time appointment','twirling a pen before every answer','反复出现的小动作是 mannerism。'),Q('mannerism',4,1,'Mannerism is related to?','manner','malt','mandarin','manner','mannerism 由 manner 加 -ism 构成。','word-formation')]});
D('manners',{etymology:E('Manners is the plural form of manner; it commonly means polite behavior in social situations.','manners'),contexts:[C('manners.s1','餐桌礼仪','The children practiced their table manners by waiting until everyone had been served before beginning to eat.','孩子们练习餐桌礼仪，等所有人都上好菜后才开始吃饭。','The children practiced their table manners / by waiting / until everyone had been served / before beginning to eat.','manners.s1 指社会交往中的礼貌行为。','等待所有人上菜再开动体现餐桌礼貌。')],mistakes:[M('She showed good manners by interrupting every speaker, pushing ahead in line, and refusing to say thank you.','She showed good manners by listening without interrupting and thanking the host.','插话、插队和拒谢都不是礼貌举止。')],quiz:[Q('manners',1,1,'Good manners include?','polite behavior toward others','a type of greenhouse tree','a legal order','polite behavior toward others','manners.s1 指礼貌、举止。'),Q('manners',2,1,'Which action shows good table manners?','waiting until everyone is served','taking food from another person’s plate','speaking with a full mouth at every moment','waiting until everyone is served','等大家都上好菜再开动较有礼貌。'),Q('manners',3,1,'“Mind your manners” means?','behave politely','repair a machine','measure the jaw','behave politely','该表达提醒人注意礼貌。'),Q('manners',4,1,'Manners in this sense usually takes which form?','plural','singular only','past tense','plural','礼貌义通常用复数 manners。','plural')]});
D('manoeuvre',{etymology:E('Manoeuvre is the British spelling of maneuver; it can mean a strategic move, a military exercise, or the act of skillfully moving something into position.','manoeuvre'),contexts:[C('manoeuvre.s3','港口调度','The tugboat manoeuvred the barge through the narrow channel and into the sheltered dock.','拖船巧妙地把驳船驶过狭窄水道，送入避风码头。','The tugboat manoeuvred the barge / through the narrow channel / and into / the sheltered dock.','manoeuvre.s3 作动词，指熟练地操纵某物到达合适位置。','拖船在狭窄水道中控制驳船转向。')],mistakes:[M('The tugboat manoeuvred the barge into the dock by abandoning control and letting it drift into rocks.','The tugboat manoeuvred the barge through the channel with careful steering.','失控漂流撞礁不是熟练操纵。')],quiz:[Q('manoeuvre',1,1,'A clever manoeuvre may be?','a strategic move to gain advantage','a mammal’s milk gland','a shopping center','a strategic move to gain advantage','manoeuvre.s1 指策略手段。'),Q('manoeuvre',2,2,'A military manoeuvre is?','a planned movement or exercise by troops','a clothing display model','a medical illness','a planned movement or exercise by troops','manoeuvre.s2 指军事演习或调动。'),Q('manoeuvre',3,3,'To manoeuvre a boat is to?','steer it skillfully into position','spread fertilizer on a field','write a manifesto','steer it skillfully into position','manoeuvre.s3 指巧妙操纵使就位。'),Q('manoeuvre',4,1,'Manoeuvre is spelled this way in?','British English','only Mandarin','mathematical notation','British English','manoeuvre 是英式拼法，maneuver 为美式拼法。','spelling')]});
D('manor',{etymology:E('Manor comes from Old French manoir, “dwelling,” ultimately from Latin manere “remain”; it names a large country house and the estate around it.','manor'),contexts:[C('manor.s1','乡村建筑','The manor stands above the village, with a walled garden and fields that once belonged to the estate.','这座庄园宅邸矗立在村庄上方，旁边有一座围墙花园和曾属于庄园的田地。','The manor stands / above the village / with a walled garden / and fields that once belonged to the estate.','manor 指乡村中的大宅邸及其周围地产。','住宅、花园和田地共同构成庄园。')],mistakes:[M('The family called its tiny rented room a manor even though it had no country estate or large house.','The family lived in a manor surrounded by estate grounds and outbuildings.','小出租房间不符合 manor 的庄园宅邸含义。')],quiz:[Q('manor',1,1,'A manor is traditionally?','a large country house with its estate','a small wooden hammer','a human-shaped clothing model','a large country house with its estate','manor.s1 指庄园宅邸。'),Q('manor',2,1,'Which place might include a manor?','a rural estate with a large house and grounds','a single city bus stop','a laboratory microscope','a rural estate with a large house and grounds','庄园宅邸常位于乡村地产中。'),Q('manor',3,1,'Manor is most closely related to a?','country estate','shopping mall','computer virus','country estate','manor 与乡村地产相关。'),Q('manor',4,1,'A manor is generally larger and more estate-like than a?','small rented room','mansion','country house','small rented room','小出租房不具庄园规模。')]});
D('mansion',{etymology:E('Mansion comes from Latin mansio, “a staying or dwelling,” from manere “remain”; it usually means a very large expensive house and in British usage can name a large apartment building.','mansion'),contexts:[C('mansion.s2','英国房产','The old mansion was divided into spacious flats, each with its own entrance from the central stairwell.','这栋旧式高级公寓楼被分成宽敞的公寓套房，每套都可从中央楼梯间进入。','The old mansion was divided / into spacious flats / each with its own entrance / from the central stairwell.','mansion.s2 在英式用法中可指高级公寓楼。','原建筑被分隔成多套公寓。')],mistakes:[M('The estate agent called the detached cottage a mansion block even though it contained no flats and was not a large building.','The estate agent described the large building divided into expensive flats as a mansion block.','单独的小屋不是大型公寓楼。')],quiz:[Q('mansion',1,1,'A mansion is usually a?','very large, expensive house','small temporary shelter','piece of agricultural fertilizer','very large, expensive house','mansion.s1 指豪宅。'),Q('mansion',2,2,'In British usage, a mansion may also be?','a large building divided into expensive flats','a shopping arcade','a government command','a large building divided into expensive flats','mansion.s2 可指高级公寓楼。'),Q('mansion',3,1,'Which property is most likely a mansion?','a huge luxurious residence','a one-room garden shed','a public bench','a huge luxurious residence','大型豪华住宅是 mansion。'),Q('mansion',4,1,'A mansion is generally associated with?','great size and expense','a wooden hammer','a formal election mandate','great size and expense','mansion 通常规模大且昂贵。')]});
D('mantel',{etymology:E('Mantel comes from French mantel, “cloak,” and is related to mantle; it names the shelf or facing above a fireplace.','mantel'),contexts:[C('mantel.s1','室内布置','She placed the family photograph on the mantel above the living-room fireplace.','她把全家福放在客厅壁炉上方的壁炉台上。','She placed the family photograph / on the mantel / above the living-room fireplace.','mantel 指壁炉上方的台面或装饰架。','照片摆在壁炉上方的搁板上。')],mistakes:[M('The vase stood on the mantel beneath a fireplace that was actually located on the roof outdoors.','The vase stood on the mantel shelf above the indoor fireplace.','mantel 是室内壁炉上方的台面。')],quiz:[Q('mantel',1,1,'A mantel is the shelf above a?','fireplace','shopping mall entrance','mammal’s jaw','fireplace','mantel.s1 指壁炉台。'),Q('mantel',2,1,'Where might someone place a clock in a living room?','on the mantel','inside a mandible','under a mangrove root','on the mantel','壁炉台常摆钟或装饰品。'),Q('mantel',3,1,'Which spelling names the shelf above a fireplace?','mantel','mantle only','manacle','mantel','mantel 指壁炉台；mantle 是另一词。','confusable'),Q('mantel',4,1,'A mantel is part of a room’s?','fireplace area','garden fertilizer','computer software','fireplace area','mantel 属于壁炉结构。')]});
D('mantle',{etymology:E('Mantle comes from Old English mentel and Latin mantellum, “cloak”; it can mean a loose sleeveless cloak, a covering, or Earth’s hot rocky layer between crust and core.','mantle'),contexts:[C('mantle.s3','地球科学','The mantle slowly circulates heat beneath the crust and influences the movement of tectonic plates.','地幔在地壳下方缓慢传递热量，并影响构造板块的运动。','The mantle slowly circulates heat / beneath the crust / and influences / the movement of tectonic plates.','mantle.s3 指地壳与地核之间的炽热岩石层。','地幔的热运动与板块活动相关。')],mistakes:[M('The geologist described the mantle as a layer of air above the atmosphere rather than hot rock between crust and core.','The geologist described the mantle as the hot rocky layer beneath Earth’s crust.','地幔是地球内部岩石层，不是大气层以上的空气。')],quiz:[Q('mantle',1,1,'A mantle can be a?','loose sleeveless cloak','wooden mallet','large shopping center','loose sleeveless cloak','mantle.s2 指披风。'),Q('mantle',2,1,'To mantle a hill in fog is to?','cover it as if with a cloak','measure its longitude','manacle a visitor','cover it as if with a cloak','mantle.s1 作动词表示覆盖。'),Q('mantle',3,3,'Earth’s mantle lies between the?','crust and core','ocean and clouds','North and South Poles','crust and core','mantle.s3 指地壳和地核间的地幔。'),Q('mantle',4,1,'Which phrase is natural in geology?','the Earth’s mantle','the Earth’s mantel shelf','the Earth’s manacle','the Earth’s mantle','地质学中使用 mantle 指地幔。','collocation')]});
D('manual',{etymology:E('Manual comes from Latin manualis, “of the hand,” from manus “hand”; it can describe work done by hand, a control operated by a person, or an instruction book.','manual'),contexts:[C('manual.s3','设备说明','The technician consulted the manual before resetting the pressure valve.','技术人员在重置压力阀之前查阅了说明书。','The technician consulted the manual / before resetting / the pressure valve.','manual.s3 作名词，指说明如何操作或使用某物的手册。','说明书提供了重置阀门的步骤。')],mistakes:[M('She called the instruction book a manual even though it contained no directions and was only a blank notebook.','She called the booklet a manual because it explained how to operate the equipment.','空白笔记本没有说明内容，不是操作手册。')],quiz:[Q('manual',1,1,'Manual labor is work done?','by hand rather than by machine','only by an automatic system','with a computer virus','by hand rather than by machine','manual.s1 指手工完成的。'),Q('manual',2,2,'A manual transmission is controlled?','by a person rather than automatically','only by a computer with no driver','by the vehicle’s paint color','by a person rather than automatically','manual.s2 指手动控制的。'),Q('manual',3,3,'A user manual tells you?','how to use or operate something','how to grow a mammal','who won an election','how to use or operate something','manual.s3 指使用说明书。'),Q('manual',4,1,'Manual is related to the Latin word for?','hand','voice','fireplace','hand','manual 源于表示“手”的拉丁词。','word-formation')]});
D('manually',{etymology:E('Manually is the adverb from manual; it means done by hand or controlled directly by a person rather than an automatic system.','manually'),contexts:[C('manually.s1','系统操作','Because the sensor had failed, an operator manually entered the temperature readings every hour.','由于传感器故障，操作员每小时手动输入一次温度读数。','Because the sensor had failed / an operator manually entered / the temperature readings / every hour.','manually 表示由人用手或直接操作，而非自动完成。','读数由操作员逐项输入。')],mistakes:[M('The system entered the readings manually even though no person touched it and an automatic sensor recorded everything.','The operator entered the readings manually using the control panel.','完全由传感器自动记录不是人工操作。')],quiz:[Q('manually',1,1,'To enter data manually is to enter it?','by a person rather than automatically','without seeing or touching any controls','only by satellite','by a person rather than automatically','manually.s1 指手动地。'),Q('manually',2,1,'Which sentence uses manually correctly?','The worker manually opened the gate.','The gate manually opened itself by automation.','The manually was on the shelf.','The worker manually opened the gate.','工人亲自操作开门是手动完成。'),Q('manually',3,1,'A device operated manually requires?','direct human control','no human input under any conditions','fertilizer','direct human control','手动设备需要人员直接控制。'),Q('manually',4,1,'Manually is the adverb related to?','manual','manure','manner','manual','manually 由 manual 加 -ly 构成。','word-formation')]});
D('manufacturable',{etymology:E('Manufacturable is formed from manufacture with -able; it describes a design or material that can practically be made in production.','manufacturable'),contexts:[C('manufacturable.s1','产品设计','The revised casing is manufacturable with the factory’s existing molds and does not require custom machinery.','修改后的外壳可以用工厂现有模具生产，无需定制机械。','The revised casing is manufacturable / with the factory’s existing molds / and does not require / custom machinery.','manufacturable 指设计或材料能够实际投入制造生产。','现有设备可以按计划生产该外壳。')],mistakes:[M('The prototype was manufacturable even though no available process could produce it and every material failed testing.','The design became manufacturable after engineers adapted it to the factory’s standard process.','没有可行生产流程就不能称可投产。')],quiz:[Q('manufacturable',1,1,'A manufacturable design can be?','made using a practical production process','described but never produced by any method','used only as a fertilizer','made using a practical production process','manufacturable.s1 指能够投产的。'),Q('manufacturable',2,1,'Engineers test manufacturability to learn whether?','a design can be produced reliably','a manager can grow a mane','a mandate is legally valid','a design can be produced reliably','设计要验证能否稳定生产。'),Q('manufacturable',3,1,'Which product is manufacturable?','one that can be made with available tools and materials','one whose parts cannot be assembled by any process','one that exists only as an impossible drawing','one that can be made with available tools and materials','有可行工艺生产的产品可称 manufacturable。'),Q('manufacturable',4,1,'Manufacturable is related to the verb?','manufacture','manipulate','manacle','manufacture','manufacturable 由 manufacture 加 -able 构成。','word-formation')]});
D('manufacture',{etymology:E('Manufacture comes through French from Latin manufactura, “making by hand,” from manus “hand” and factura “a making”; it can mean factory production or inventing a false story.','manufacture'),contexts:[C('manufacture.s2','事实核查','The spokesperson manufactured an excuse about a power failure, but maintenance records showed the system had worked normally.','发言人编造了停电的借口，但维护记录显示系统一直正常运行。','The spokesperson manufactured an excuse / about a power failure / but maintenance records showed / the system had worked normally.','manufacture.s2 作动词，指编造故事、借口或证据。','记录证实停电说法并不真实。')],mistakes:[M('The spokesperson manufactured the excuse by repeating a verified report that accurately described the power failure.','The spokesperson manufactured the excuse by inventing a power failure that never occurred.','真实准确的报告不是编造。')],quiz:[Q('manufacture',1,1,'To manufacture goods is to?','make them in quantity, often in factories','search for missing goods','use a product without making it','make them in quantity, often in factories','manufacture.s1 指批量制造。'),Q('manufacture',2,2,'To manufacture a story is to?','invent it, often falsely','print a verified source accurately','repair a machine','invent it, often falsely','manufacture.s2 可指捏造。'),Q('manufacture',3,3,'Manufacture as a noun can mean?','the process or industry of factory production','a human-shaped clothing model','the Earth’s mantle','the process or industry of factory production','manufacture.s3 指制造过程或制造业。'),Q('manufacture',4,1,'A factory may manufacture?','bicycles in large quantities','a natural mangrove forest','a human mandible','bicycles in large quantities','工厂批量生产自行车。')]});
D('manufacturer',{etymology:E('Manufacturer is formed from manufacture with -er; it names a company or firm that produces goods, usually in quantity.','manufacturer'),contexts:[C('manufacturer.s2','供应链管理','The appliance manufacturer recalled the model after testing found a defect in its power cable.','测试发现电源线存在缺陷后，这家电器生产企业召回了该型号。','The appliance manufacturer recalled the model / after testing found / a defect / in its power cable.','manufacturer 指生产商品的公司或企业，常涉及某行业的批量生产。','企业负责生产电器并在发现缺陷后召回产品。')],mistakes:[M('The retailer was called the manufacturer even though it only sold the appliances and had no role in producing them.','The company that produced the appliances was their manufacturer.','只销售商品的零售商不是制造商。')],quiz:[Q('manufacturer',1,1,'A car manufacturer is a company that?','produces cars','only drives cars to work','writes political speeches','produces cars','manufacturer.s1 指生产商。'),Q('manufacturer',2,2,'A manufacturer in a specific industry is?','a firm operating in that production sector','a person who only buys the finished goods','a type of agricultural waste','a firm operating in that production sector','manufacturer.s2 指某行业的生产企业。'),Q('manufacturer',3,1,'Who is most likely the manufacturer of a phone?','the company that built it','the shop that resold one used phone','the person who received it as a gift','the company that built it','生产手机的公司是制造商。'),Q('manufacturer',4,1,'Manufacturer is related to the verb?','manufacture','manure','manner','manufacture','manufacturer 由 manufacture 加 -er 构成。','word-formation')]});
D('manufacturing',{etymology:E('Manufacturing is formed from manufacture with -ing; as a noun it names the business or industry of making goods in factories.','manufacturing'),contexts:[C('manufacturing.s1','产业报告','Manufacturing in the region grew after the new rail line reduced the cost of shipping components.','新铁路降低了零部件运输成本后，该地区的制造业有所增长。','Manufacturing in the region grew / after the new rail line reduced / the cost / of shipping components.','manufacturing 指在工厂生产商品的行业或活动。','运输成本下降促进了该地区的工厂生产。')],mistakes:[M('The report said manufacturing expanded even though every factory closed and no goods were produced.','The report said manufacturing expanded as local factories increased production.','工厂停产与制造业扩张相矛盾。')],quiz:[Q('manufacturing',1,1,'Manufacturing is the business of?','making goods in factories','growing only wild plants','treating patients in a clinic','making goods in factories','manufacturing.s1 指制造业。'),Q('manufacturing',2,1,'A manufacturing region is likely to have?','factories producing goods','only private homes and no industry','a large number of mannequins only','factories producing goods','制造业地区通常有生产商品的工厂。'),Q('manufacturing',3,1,'Which phrase is natural?','manufacturing industry','manufacturing of a person’s manners','manufacturing by the river as a noun phrase only','manufacturing industry','manufacturing industry 是常见搭配。','collocation'),Q('manufacturing',4,1,'Manufacturing is related to?','manufacture','malaria','manacle','manufacture','manufacturing 由 manufacture 派生。','word-formation')]});
D('manure',{etymology:E('Manure came through Old French from a word meaning to work the land; it names animal waste used to fertilize soil and the act of applying it.','manure'),contexts:[C('manure.s2','农田管理','The growers manured the orchard in early spring and mixed the material into the soil around each tree.','种植者在早春给果园施了粪肥，并把肥料混入每棵树周围的土壤。','The growers manured the orchard / in early spring / and mixed the material / into the soil around each tree.','manure.s2 作动词，表示把粪肥施到土地上。','果园的土壤被施肥以改善栽培条件。')],mistakes:[M('The farmer manured the orchard by removing every soil nutrient and spreading only clean water over the trees.','The farmer manured the orchard by applying animal waste as fertilizer.','施清水不是施粪肥。')],quiz:[Q('manure',1,1,'Manure is commonly used as?','fertilizer made from animal waste','a tool for shaping metal','a computer security program','fertilizer made from animal waste','manure.s1 指粪肥。'),Q('manure',2,2,'To manure a field is to?','spread manure on it','remove all its soil','build a mansion there','spread manure on it','manure.s2 作动词指施肥。'),Q('manure',3,1,'Which material is manure?','animal waste used to enrich soil','a citrus fruit peel only','a wooden-headed hammer','animal waste used to enrich soil','动物排泄物用于肥田时称 manure。'),Q('manure',4,1,'Manure helps plants by?','adding nutrients to soil','making a computer malfunction','restricting their roots from all water','adding nutrients to soil','肥料改善土壤养分。')]});

})();
